-- ---------------------------------------------- 1. Тайлбар (431) ---
update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('723c2607-3b43-4055-a9f0-f0cb87533c62'::uuid, '四 гэдэг нь «дөрөв» гэсэн тооны нэр (утга). Зурагтай холбоотой асуултад зураг өгөгдөөгүй тул шууд харьцуулах боломжгүй, харин өгөгдсөн зөв хариулт нь × буюу таарахгүй гэж заасан байна — зурагтай тулгаж үз.'),
  ('d51581b5-c337-4ff1-b230-a26dd5b8bafd'::uuid, '猫 гэдэг нь «муур» гэсэн амьтны нэр. Өгөгдсөн зөв хариулт нь √ буюу зурагтай таарч байна гэсэн үг — зурагтай тулгаж үз.'),
  ('65fea471-4959-43ab-af0f-591de4cc9075'::uuid, '多 гэдэг нь «олон, их» гэсэн утгатай тэмдэг нэр. Өгөгдсөн зөв хариулт нь √ буюу зурагтай таарч байна гэсэн үг — зурагтай тулгаж үз.'),
  ('eba04a42-dd73-4f1f-8f51-210675bcf343'::uuid, '喝 гэдэг нь «уух» гэсэн үйл үг. Өгөгдсөн зөв хариулт нь √ буюу зурагтай таарч байна гэсэн үг — зурагтай тулгаж үз.'),
  ('83617bcd-693d-4873-9c2f-ca8b215b3d84'::uuid, '出租车 гэдэг нь «такси» гэсэн утгатай нэр үг. Өгөгдсөн зөв хариулт нь × буюу зурагтай таарахгүй байна гэсэн үг — зурагтай тулгаж үз.'),
  ('aece6de3-ad96-424d-b437-d808135f0bb2'::uuid, '妈妈，这个字我会写了。 гэдэг нь «Ээж ээ, би энэ үсгийг бичиж сурлаа» гэсэн утгатай — хүүхэд бичиж сурсанаа ээждээ хэлж буй өгүүлбэр. Өгөгдсөн зөв хариулт D зурагтай тулгаж үз.'),
  ('b874a08b-68e2-434c-9c7b-54594fc1103a'::uuid, '喂，你好，是李先生吗？ гэдэг нь утсаар ярьж «Байна уу, та Ли гуай мөн үү?» гэж асуусан өгүүлбэр. Өгөгдсөн зөв хариулт B зурагтай тулгаж үз.'),
  ('5618074a-e4d1-43b8-b561-65f71da02d22'::uuid, '这个衣服怎么样？ гэдэг нь «Энэ хувцас ямар байна?» гэсэн утгатай, хувцас үзэж буй агшинг тодорхойлно. Өгөгдсөн зөв хариулт F зурагтай тулгаж үз.'),
  ('2771fa18-1dfc-4b51-b5ec-442c28f93368'::uuid, '没关系，我这里有钱。 гэдэг нь «Зүгээр ээ, надад мөнгө байна» гэсэн утгатай, мөнгөгүй байгаа хүнийг тайтгаруулж буй өгүүлбэр. Өгөгдсөн зөв хариулт A зурагтай тулгаж үз.'),
  ('99c9d763-bd67-44c6-89b9-3f1e03ffd1f5'::uuid, '下雨了，天气有点儿冷。 гэдэг нь «Бороо орлоо, цаг агаар жаахан хүйтэн байна» гэсэн утгатай. Өгөгдсөн зөв хариулт C зурагтай тулгаж үз.'),
  ('a623e180-2d6c-41b3-a509-9a917965066e'::uuid, '打电话的那个人是谁？ гэдэг нь «Утсаар ярьж байгаа хүн хэн бэ?» — 谁 (хэн) гэж хүн асуусан тул хариулт нь хүнийг заасан 我同学 (миний ангийн найз) байх ёстой. 27块 (үнэ), 很好 (ямар байна), 在这儿 (хаана), 8月1日 (хэзээ) зэрэг нь өөр төрлийн асуултад тохирно.'),
  ('effa4b0c-6ba5-474f-a4bc-49778d119bea'::uuid, '你什么时候去北京？ гэдэг нь «Чи хэзээ Бээжин рүү явах вэ?» — 什么时候 (хэзээ) гэж цаг хугацаа асуусан тул хариулт нь огноо заасан 8月1日 байх ёстой. Бусад сонголтууд (үнэ, хүн, газар, чанар) цаг хугацааны хариулт биш.'),
  ('38dfe54a-7666-45fe-8795-715da58c4a8e'::uuid, '她的汉语怎么样？ гэдэг нь «Түүний хятад хэл ямар байна вэ?» — 怎么样 (ямар байна) гэж чанар асуусан тул хариулт нь 很好 (маш сайн) байх ёстой. Энэ нь цор ганц чанар илэрхийлсэн сонголт.'),
  ('6f2c1c1c-3324-4ed0-87b7-b8e86ae9d905'::uuid, '我的杯子怎么不见了？ гэдэг нь «Миний аяга яагаад алга болов?» — энэ нь мөн байршил хайж буй агуулгатай тул хариулт нь газар заасан 在这儿 (энд байна) байх ёстой.'),
  ('717be177-a82d-4c98-b23e-22ef77601d65'::uuid, '这些苹果多少钱？ гэдэг нь «Эдгээр алим хэдэн төгрөг вэ?» — 多少钱 (хэд вэ, үнэ) гэж үнэ асуусан тул хариулт нь үнэ заасан 27块 байх ёстой.'),
  ('72c49306-2be6-46f7-b7a8-650469a343be'::uuid, '«我爸爸在医院（ ），他是医生» — 在医院 (эмнэлэгт) гэсний ард юу хийдгийг заасан үйл үг хэрэгтэй, дараах өгүүлбэрт «тэр эмч» гэсэн тул зөв хариулт 工作 (ажиллах). 上 (гарах), 爱 (хайрлах), 大 (том), 名字 (нэр), 朋友 (найз) нь энд тохирохгүй.'),
  ('3b77b0ee-2932-4235-a916-ae16305eaa6a'::uuid, '«我在中国住了3年，认识了很多（ ）» — 认识 (танилцах) үйл үгийн ард хүн заасан нэр үг хэрэгтэй тул зөв хариулт 朋友 (найз нар): «олон найз нартай танилцлаа». 工作 (ажил), 名字 (нэр) зэрэг хүн биш тул тохирохгүй.'),
  ('ee4badf4-57ec-41bf-9573-d3604eb7759c'::uuid, '«椅子（ ）的东西都是你的？» — 椅子 (сандал) ба 的 хоёрын хооронд байрлал заасан үг хэрэгтэй тул зөв хариулт 上 (дээр): «сандлын дээрх юмс». Бусад сонголт байрлал заахгүй.'),
  ('0a1ee52b-6f5b-438e-b4d5-b2843bd624ed'::uuid, '«你儿子多（ ）了？» — «一岁零6个月» (нэг нас хагас) гэж насаар хариулсан тул 多大了 (хэдтэй болсон бэ) гэсэн тогтсон хэллэл ашиглагдана, иймд зөв хариулт 大 (том, нас). 上、爱、名字、朋友、工作 нь насны асуултад тохирохгүй.'),
  ('1c55130e-c889-47cc-887e-a660c922ebec'::uuid, '«她（ ）吃水果» — жимс их авсан шалтгааныг тайлбарлаж буй тул 爱吃 (идэх дуртай) гэсэн хэллэл хэрэгтэй, зөв хариулт 爱 (хайрлах, дуртай байх). Бусад үг үйл үгийн өмнө ийм утга өгөхгүй.'),
  ('17e85d99-b522-47d4-99c6-a41f78445530'::uuid, '欢迎您，请这边走。 гэдэг нь «Тавтай морил, энэ тийшээ явна уу» гэсэн угтах, зам зааж буй өгүүлбэр. Өгөгдсөн зөв хариулт A зурагтай тулгаж үз.'),
  ('ec6f01aa-d093-479c-b10a-d921e32d2367'::uuid, '让我看看里面是什么东西。 гэдэг нь «Дотор нь юу байгааг надад үзүүлээч» гэсэн утгатай, ямар нэгэн зүйлийн дотрыг харах хүсэлт. Өгөгдсөн зөв хариулт F зурагтай тулгаж үз.'),
  ('a905e95c-f009-4601-8c2f-03beaa09d609'::uuid, '这次考试她考得非常好。 гэдэг нь «Энэ удаагийн шалгалтад тэр маш сайн дүн авсан» гэсэн утгатай. Өгөгдсөн зөв хариулт E зурагтай тулгаж үз.'),
  ('53c1f403-d757-4aa6-a58b-1aea786decf8'::uuid, '我妻子给我打了4个电话，我一个都没听到。 гэдэг нь «Эхнэр минь надад 4 удаа утасдсан ч би нэгийг нь ч сонсоогүй» гэсэн утгатай. Өгөгдсөн зөв хариулт C зурагтай тулгаж үз.'),
  ('5ad9022e-f612-47da-a00b-94a423b91809'::uuid, '我这就穿好了，你再等一下。 гэдэг нь «Би одоо хувцаслаад дуусна, чи жаахан хүлээгээрэй» гэсэн утгатай. Өгөгдсөн зөв хариулт B зурагтай тулгаж үз.'),
  ('304e8796-08e8-459a-b98d-f81d29837312'::uuid, '你来（ ）一下这个问题 гэдэгт цоорхойн өмнө 来 (ирж), ард нь 一下这个问题 (энэ асуултыг) байгаа тул “хариулах” гэсэн үйл үг хэрэгтэй. 回答 (хариулах) яг таарна. 件 (ширхэг), 姓 (овогтой), 离 (хол), 贵 (үнэтэй), 身体 (бие) утгаараа тохирохгүй.'),
  ('65ee574b-f2b1-49b7-8e89-2133b9bb6984'::uuid, '帮助人是一（ ）很快乐的事情 гэхэд цоорхой нь тооны үг 一-ийн ард, 事情 (хэрэг явдал) нэр үгийн өмнө байгаа тул ХЭМЖИХ ҮГ хэрэгтэй. 件 нь хэрэг явдал тоолох хэмжих үг тул зөв, бусад нь үйл үг, нэр үг тул тохирохгүй.'),
  ('104a6866-0a20-4240-b7c5-dc2fefa085e7'::uuid, '多吃水果对（ ）好 гэдэгт 对...好 (...-д сайн) бүтэц байгаа тул ямар зүйлд сайн болохыг заасан нэр үг хэрэгтэй. Жимс их идэх нь 身体 (бие)-д сайн гэсэн утга тохирно. Бусад сонголт энд утгын хувьд таарахгүй.'),
  ('5c9ba1f0-bd63-4c7c-9d79-049855986e8d'::uuid, '我（ ）王，叫王元元 гэдэгт 叫王元元 (Ван Юаньюань гэдэг) гэж нэрээ хэлэхийн өмнө овгоо хэлэх ёстой тул 姓 (овогтой) гэсэн үйл үг хэрэгтэй — 姓王 (Ван овогтой). Бусад үг энд утга нийцэхгүй.'),
  ('bb75f486-e100-49c0-b9db-9c84dfedddb2'::uuid, '你家（ ）学校远吗 гэдэгт ард нь 远 (хол) байгаа тул хоёр газрын зайг заасан 离 (-аас хол/ойрхон) угтвар үг хэрэгтэй — 离学校远 (сургуулиас хол). Бусад сонголт энд утга оноогүй.'),
  ('2e27e60d-b75b-411d-ba56-297a300d5d17'::uuid, 'Эх бичвэрт 天阴了，可能快下雨了 (тэнгэр бүрхэг, удахгүй бороо орж магадгүй) гэж байгаа буюу бороо ОДОО ХАРАХАД ОРООГҮЙ, харин орох магадлалтай гэсэн үг. Харин өгүүлбэр нь 外面已经下雨了 (гадаа аль хэдийн бороо орж байна) гэж ОДОО ОРЖ БАЙГАА мэт хэлж байгаа тул эх бичвэртэй зөрчилдөж × болно.'),
  ('f4ff7a3b-834a-4b99-8219-150d4e74c642'::uuid, '爸爸明天早上9点下飞机，我们7点从家去机场就可以 (аав маргааш өглөө 9 цагт нисэх онгоцноос буух тул бид 7 цагт гэрээсээ буудал руу явна) гэдгээс тэд маргааш өглөө нисэх буудал руу явна гэдэг тодорхой батлагдана — тиймээс √ зөв.'),
  ('fa4115af-033f-42b3-841d-b72b64ad8d12'::uuid, 'Эх бичвэрт 写得很有意思 (маш сонирхолтой бичсэн) гэж номыг сайшааж байгаа тул тэр хүн номыг сайн биш гэж хэлэх боломжгүй. Харин өгүүлбэр 他觉得那本书不好看 (тэр тэр номыг сайн биш гэж боддог) гэж эсрэгээр хэлж байгаа тул × болно.'),
  ('88c395da-f362-44a7-ac41-64779651aa86'::uuid, '这儿太漂亮了，真希望我们能多住几天再走 (энд маш үзэсгэлэнтэй, хэдэн хоног илүү байгаад явмаар байна) гэдгээс тэр газарт их дуртай нь тодорхой харагдаж байгаа тул 他很喜欢这里 (тэр энд их дуртай) гэдэг зөв √ болно.'),
  ('ddc9b831-3d4d-42c0-825c-67ac9b901160'::uuid, 'Эх бичвэрт 这个电脑是我们店里卖得最好的 (энэ компьютер манай дэлгүүрт хамгийн сайн зарагддаг) гэж байгаа тул худалдан авагч цөөн гэсэн 买这个电脑的人很少 (энэ компьютерийг авдаг хүн цөөхөн) гэдэгтэй шууд зөрчилдөнө — × зөв.'),
  ('07aee30c-1221-4748-bc68-95d707a4d824'::uuid, '没有，我想下班后到火车站再看看 (үгүй, ажлаас чөлөөлөгдсөний дараа галт тэрэгний буудал руу очиж дахин харья) гэдэг нь тийз авах тухай асуултад өгсөн хариулт. D сонголт 回家的票你买好了吗？(гэр лүү харих тийзээ авсан уу?) гэдэгтэй утгаараа холбогдоно. Бусад сонголт огт өөр сэдэвтэй тул тохирохгүй.'),
  ('cc835278-8322-41ae-a853-d84aefff6995'::uuid, '那时候它还不到一岁 (тэр үед энэ хараахан нэг настай болоогүй байсан) өгүүлбэр дэх 它 (энэ, амьтныг заана) гэдэг нь C сонголтын 小狗是去年哥哥送我的 (нохойг ах маань өнгөрсөн жил надад өгсөн) өгүүлбэрийн 小狗 (нохой)-той холбогдож байна.'),
  ('98fe9acc-9f71-4aec-a39f-3eb890a0ce89'::uuid, '上面有名字吗？(дээр нь нэр бий юу?) гэсэн асуулт ямар нэг зүйлийн (ном) тухай байх ёстой. F сонголт 这本汉语书是谁的？(энэ хятад хэлний ном хэний вэ?) гэж номны эзнийг асууж байгаа тул холбогдоно — 上面 гэдэг нь номны нүүрэн дээрх нэрийг хэлж байна.'),
  ('22e46369-9249-4e78-ac57-953400e29afc'::uuid, '晚上我们去唱歌怎么样？(орой нь дуулах уу?) гэсэн саналд A сонголт 我有点儿累，想早点儿睡觉 (би жаахан ядарсан, эрт унтмаар байна) гэж татгалзсан хариу өгч байгаа тул зохимжтой.'),
  ('801abfe1-3172-4f00-80b5-fb745abdb74a'::uuid, '你少看了个零吧？那是6000多 (чи нэг тэг дутуу харсан биз дээ? тэр 6000-аас дээш) гэдэг нь үнийн талаар байгаа тул B сонголт 这个白色的手机不错，还很便宜，就几百块钱 (энэ цагаан утас сайхан, хямд, ердөө хэдэн зуун юань) гэдгийн үнийг засаж байна.'),
  ('77ea8e1d-970e-4f52-ba09-9ea0c2ac0360'::uuid, '这个字我会写了，谢谢老师 (энэ үсгийг бичиж чадах боллоо, багшдаа баярлалаа) гэсэн талархалд E сонголт 不客气，还有不懂的吗？(зүгээр ээ, дахиад ойлгоогүй зүйл байна уу?) гэж хариулт өгч байгаа нь зохимжтой.'),
  ('e39c0a54-60c3-4db5-93ae-ab90d26cdeaf'::uuid, '你来中国多长时间了？(чи Хятадад ирээд хэр удаж байна?) гэсэн асуултад A сонголт 我是4月1日到北京的，快三个月了 (би 4-р сарын 1-нд Бээжинд ирсэн, ойролцоогоор 3 сар болж байна) гэж хугацаагаар хариулж байна.'),
  ('79d2a3e6-46f6-46f1-916a-857b89d088fa'::uuid, '那个穿红衣服的就是我儿子 (тэр улаан хувцастай хүн бол миний хүү) гэдэгт D сонголт 他在那儿和孩子们踢足球呢 (тэр тэнд хүүхдүүдтэй хөл бөмбөг тоглож байна) гэж хүүгийн байршил, үйлдлийг тодорхойлж байна.'),
  ('f2a0b58f-9530-4928-91bb-d581c5bc6c61'::uuid, '因为我不知道怎么说 (яагаад гэвэл яаж хэлэхээ мэдэхгүй байсан) гэдэг нь шалтгаан заасан хариулт тул C сонголт 我还没告诉她这件事 (би түүнд энэ хэргийг хараахан хэлээгүй байна) гэсэн “яагаад хэлээгүй вэ” асуултын хариу болно.'),
  ('9c801b99-5df7-401e-953e-a4f745658fc9'::uuid, '好的，这个有点儿热，你慢点儿喝 (за, энэ жаахан халуун байна, аажуухан ууна уу) гэдэг нь ундаа сүйлэх тухай тул B сонголт 再给我来一杯牛奶吧 (надад дахиад нэг аяга сүү өгөөч) гэсэн захиалгад өгсөн хариу болно.'),
  ('0dc89dd1-23bf-49b2-832b-d7cb3db241a8'::uuid, '97分？你这次考试成绩不错啊 (97 оноо уу? Энэ удаагийн шалгалтын дүн чинь сайн байна) гэсэн магтаалд B сонголт 没想到才半年的时间，你的汉语水平就提高了这么多！(ердөө хагас жилийн дотор хятад хэлний чинь түвшин ийм их дэвшсэнийг үнэхээр төсөөлөөгүй!) гэж дэвшлийг тэмдэглэн хамт нийцнэ.'),
  ('442668cc-2e13-40b2-82d6-b4a3f6ced409'::uuid, '奶奶，您等一下，我去给您拿眼镜 (эмээ, жаахан хүлээгээрэй, би танд нүдний шил авчирна) гэдэг нь D сонголт 地图上的字太小了，我看不清楚 (газрын зурган дээрх үсэг хэтэрхий жижиг, тодорхой харагдахгүй байна) гэсэн нүдний шил хэрэгтэй болсон шалтгаантай холбогдоно.'),
  ('2d6aa949-b205-4316-96d0-6883d29cc9f0'::uuid, '请问，张校长的办公室是哪一间？(уучлаарай, захирал Жангийн ажлын өрөө аль нь вэ?) гэсэн асуултад C сонголт 最东边那个。但是他上午出去开会了，您下午再来？(хамгийн зүүн талынх. Гэхдээ тэр өглөө хурал дээр гарсан, та үдээс хойш ирнэ үү?) шууд хариулт болно.'),
  ('97ed2809-b1b2-45b1-bc16-d1b9bb29640a'::uuid, '房间里怎么这么热？(өрөө яагаад ийм халуун байна?) гэдэгт F сонголт 忘记开空调了，你去开一下 (агааржуулагч асаахаа мартчихсан, чи очиж асаагаарай) гэж шалтгаан, шийдлийг өгч байна.'),
  ('57f0b3be-0d8b-49fe-85ae-15866772b11b'::uuid, '我刚来这里时，他帮了我不少忙 (би энд шинээр ирэхэд тэр надад их тусалсан) гэсэн өгүүлбэрт A сонголт 小关人很好，对谁都很热情 (Сяо Гуан сайн хүн, хэнд ч халуун дулаан ханддаг) хамт “тэр” хэн болохыг тайлбарлаж байна.'),
  ('4fb070c4-5a34-4b4f-9833-5e43949742a6'::uuid, '小孩子长得真快！(хүүхдүүд үнэхээр хурдан ургадаг юм!) гэсэн ажиглалтад E сонголт 儿子去年的裤子和衬衫今年就不能穿了 (хүүгийн өнгөрсөн жилийн өмд, цамц энэ жил өмсөх боломжгүй боллоо) жишээ болж нотолж байна.'),
  ('196263f2-e6c0-4b46-ab68-6ec3fca41590'::uuid, '除了爱唱歌外，她们还很喜欢跳舞 (дуулах дуртайгаас гадна тэд бүжиглэхэд ч их дуртай) гэдэг дэх 她们 (тэд) хэн болохыг D сонголт 王阿姨和我妈妈爱好相同 (Ван эгч, ээж хоёрын сонирхол ижил) тодотгож байна.'),
  ('137382d6-363f-4ecc-b382-704627118975'::uuid, '我来介绍一下，这是我妻子小蓝 (танилцуулъя, энэ бол миний эхнэр Сяо Лань) гэсэн танилцуулгын хариу тал болгож C сонголт 这位是我的同学张乐，他现在是市第一医院的医生 (энэ бол миний ангийн найз Жан Лэ, тэр одоо хотын нэгдүгээр эмнэлгийн эмч) хосолж хоёр талын танилцуулга болно.'),
  ('3548bb2e-49df-4eeb-8726-218857fde90d'::uuid, '饿了吧？今天不吃米饭，吃面条儿 (өлссөн байх аа? өнөөдөр будаа биш гоймон идье) гэдэг хоолны бэлтгэлтэй холбоотой A сонголт 你先帮我把筷子和碗放到桌子上 (эхлээд савх, аяга ширээн дээр тавьж өгөөч) тохирно.'),
  ('316a74d0-889a-4cb3-ab1e-c983143af193'::uuid, '你出门记得带把伞 (гарахдаа шүхэр авахаа бүү март) гэдгийг B сонголт 喂，外面阴天了，我担心会下雨 (алло, гадаа бүрхэг болсон, бороо орох вий гэж санаа зовж байна) шалтгааны хувьд холбож байна.'),
  ('bd7d4f2b-bd1d-44ed-a431-33a0ce495f22'::uuid, '牛奶太甜了，（ ）放多了吧？гэдэгт 太甜了 (хэтэрхий чихэрлэг) гэсэн шалтгааныг тайлбарлах эд зүйл хэрэгтэй. 糖 (элсэн чихэр) их хийсэн тул чихэрлэг болсон гэсэн санаа тохирно. 安静 (чимээгүй), 出现 (гарч ирэх) зэрэг үйл үг энд утга оноогүй.'),
  ('f1a7c1aa-b02d-41bc-8a19-9c8874d44062'::uuid, '太阳和月亮会在同一个时候（ ）吗？гэдэгт нар, сар нэгэн зэрэг ямар үйлдэл хийж болохыг заасан үйл үг хэрэгтэй. 出现 (гарч ирэх) тохирно — нар сар нэг зэрэг тэнгэрт харагдах уу гэсэн утга. 糖, 声音 зэрэг нэр үг энд тохирохгүй.'),
  ('6e1f747b-c406-4f7e-b58d-0b46108d9de3'::uuid, '表演几点（ ）？我去接你 гэдэгт 几点 (хэдэн цагт) гэсэн асуултад тохирох, тоглолт хэзээ дуусахыг заасан үйл үг хэрэгтэй. 结束 (дуусах) зөв — тоглолт хэдэн цагт дуусах вэ гэсэн утга.'),
  ('0ec0a6e5-1ba1-4cc3-b6bb-e1305016628c'::uuid, '祝您（ ）快乐 гэдэг нь 节日快乐 (баярын мэнд хүргэе) гэсэн тогтмол хэллэгтэй бөгөөд бэлгийн тухай өгүүлбэртэй нийцнэ. 节日 (баяр) гэдэг нэр үг энд зөв тохирно.'),
  ('824efac5-e3b9-4bf1-b626-d465dcf71f7d'::uuid, '山上很（ ），早上起床的时候还能听见鸟的叫声 гэдэгт шувууны дуу сонсогдох тайван орчныг заасан шинж тэмдэг хэрэгтэй. 安静 (тайван, чимээгүй) зөв тохирно — учир нь чимээгүй байж л шувууны дуу сонсогддог.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('a02e88a8-0c04-49c6-b846-0adec15c8281'::uuid, '我的自行车半路突然（ ）了 гэдэгт унадаг дугуй замын дундуур гэнэт юу болсныг заасан үйл үг хэрэгтэй. 坏 (эвдрэх) зөв — унадаг дугуй гэнэт эвдэрсэн тул хожимдсон.'),
  ('9efd0731-74c8-47cf-8f2b-4701799d5404'::uuid, '能借你的照相机用一下吗？гэсэн хүсэлтэд «（ ）可以» гэж баталгаажуулж байгаа тул зөвшөөрлийг чангатгах үг хэрэгтэй. 当然 (мэдээж) зөв — мэдээж болно гэсэн утга.'),
  ('6b0d8109-3a02-41bd-91d1-ad0713dee205'::uuid, '我把厨房和（ ）都打扫了一下 гэдэгт 厨房 (гал тогоо)-той хамт цэвэрлэгдсэн өрөөний нэр хэрэгтэй. 洗手间 (угаалгын өрөө) зөв тохирно.'),
  ('b54c42d2-7be5-404d-bae4-6e373cf58008'::uuid, '你是今年刚（ ）工作的？гэдэгт 工作 (ажил)-ын өмнө орох үйл үг хэрэгтэй. 参加 (эхлэх, оролцох) зөв — 参加工作 (ажилд орох) гэсэн тогтсон хэллэг.'),
  ('00bb2982-eb47-4f00-bbd6-9bfa049a263a'::uuid, '你从这儿向西走1000（ ） гэдэгт зайг заасан хэмжээний нэгж хэрэгтэй. 米 (метр) зөв — 1000 метр баруун тийш явах гэсэн утга.'),
  ('b74417ec-1d35-4c00-b550-e4ac63bef121'::uuid, 'Эх бичвэрт 桌子放在中间会影响大家走路的 (ширээг голд тавивал хүмүүсийн явахад саад болно) гэсэн тул ширээг 搬到那边去 (тэр талд зөөх) буюу нэг тийш зайлуулна гэсэн үг. Тиймээс B «搬到一边» зөв. A нь яг эсрэг санаа, C-г эх бичвэрт огт дурдаагүй.'),
  ('e9f438d3-418c-4240-9001-c71baaa54848'::uuid, 'Ажилтан 服务员还是有点儿少 (үйлчлэгч арай цөөхөн байна), 大家经常忙不过来 (ажил дийлэхгүй ядна) гэж хэлж байгаа тул A «服务员少» зөв. B «工作不累» нь 忙不过来 (амжихгүй байна)-тай зөрчилддөг, C «经理要求低»-г эх бичвэрт огт хэлээгүй.'),
  ('bd0c9aa0-9814-4fb2-a60e-6b9b69d33827'::uuid, '不怕慢，只怕站 (удаан явахаас биш, зогсохоос ай) гэдэг нь 一步一步地走下去，也能走到想去的地方 (нэг нэгээр удаан ч атугай, зогсолтгүй алхвал хүрэх газраа хүрнэ) гэсэн санаа тул A «要一直努力» (байнга хичээж байх хэрэгтэй) зөв. B, C-ийн тухай эх бичвэрт байхгүй.'),
  ('50af8511-8919-4719-874e-465cd9f598d5'::uuid, '别人告诉你...你可能不会相信 (өөр хүн хэлэхэд итгэхгүй байж болно), 自己看到的...就不一样了 (өөрөө харсан бол өөр) гэж харьцуулаад 人们更愿意相信自己的眼睛 (хүмүүс өөрийн нүдэндээ илүү итгэдэг) гэсэн тул C зөв. A, B-ийг эх бичвэрт огт дурдаагүй.'),
  ('99c39a37-cacb-44d7-bb4f-c4dafbaa886d'::uuid, '他的车几乎到过这个城市的每个地方，所以他对这个城市非常了解 (тэрээр хотын бараг бүх газраар явсан тул хотыг маш сайн мэддэг) гэснээс C «很了解这个城市» зөв. B «骑车上班» нь出租车司机 (такси жолооч) гэдэгтэй зөрчилддөг, A-г огт дурдаагүй.'),
  ('10eb13f0-c59b-417d-8d00-44cf0741413c'::uuid, '以前...都是些又矮又旧的房子 (өмнө нь намхан хуучин байшингууд байсан), 没想到现在变成了一个大花园 (одоо цэцэрлэг болжээ) гэсэн тул асуулт нь 过去 (өмнөх) үеийг асуусан учир B «老房子» зөв, А «花园» бол одоогийн байдал.'),
  ('1ff26645-2870-409b-a043-7b1de9c0e9ef'::uuid, '中国人习惯把姓放在前面，把名字放在后面 (хятадууд овгоо урд, нэрээ ард тавьдаг заншилтай) гэснээс C «姓在最前面» зөв. A, B (энгийн, урт) -ийн тухай эх бичвэрт дурдаагүй.'),
  ('19481439-b212-42db-8878-6a41e66a3d3a'::uuid, '经过这件事情，我们两个的关系变得比以前更好了 (энэ явдлын дараа хоёрын харилцаа улам сайжирсан) гэснээс B «关系更好了» зөв. A «很少见面» нь 经常一起吃饭、看电影 (байнга хамт хооллодог) гэдэгтэй зөрчилддөг, C-г дурдаагүй.'),
  ('fe24c146-8694-432d-ad42-f8a33eb0fc2d'::uuid, '有时候饭也不吃...对身体很不好 (заримдаа хоол ч идэхгүй, биед их муу), 健康才是最重要的 (эрүүл мэнд хамгийн чухал) гэснээс B «健康比漂亮重要» зөв. A, C-ийн тухай яриагүй.'),
  ('27242ae2-f4c3-4b77-98d4-eda1ae0f03d0'::uuid, '想清楚后就必须马上去做 (сайн бодсоны дараа даруй хийх ёстой), 机会不等人 (боломж хүлээдэггүй) гэснээс C «想好了就去做» зөв. A, B-ийн тухай эх бичвэрт огт дурдаагүй.'),
  ('9a3b0063-c555-471c-bf53-a29d64b63c35'::uuid, '被 (被)-strой өгүүлбэрийн бүтэц: [нөлөөлөгдөгч] + 被 + [хийгч] + [үйл үг+了]. Энд 蛋糕 (бялуу) нь нөлөөлөгдөгч тул хамгийн түрүүнд, дараа нь 被我 (миний), эцэст нь 吃了 (идчихсэн) орж 蛋糕被我吃了 (Бялууг би идчихлээ) болно.'),
  ('5d6a861b-3963-469e-82f9-899b0f3439e3'::uuid, 'Бүтэц: [өгүүлэгдэхүүн]+是+一种+[тодотгол]+[нэр үг]. 猫是 (муур бол) эхэнд, дараа нь тоо/төрөл заасан 一种 (нэг төрлийн), тодотгол 爱干净的 (цэвэрч), эцэст нь нэр үг 动物 (амьтан) орж 猫是一种爱干净的动物 болно.'),
  ('49b0adc3-e1b0-495e-b21f-eb244656f751'::uuid, 'Бүтэц: [тодотгол+өгүүлэгдэхүүн]+[үйл үг]+[тоо+нэр үг]. 那个体育馆 (тэр спорт заал) нь өгүүлэгдэхүүн, 能坐 (суулгаж чадна) нь үйл үг, 两万人 (2 түмэн хүн) нь объект тул 那个体育馆能坐两万人 болно.'),
  ('3eb7e08c-274a-4407-89f1-86749da61841'::uuid, 'Бүтэц: [тодотгол+өгүүлэгдэхүүн]+长得+[зэрэгцүүлэлт]. 街道两边的树 (гудамжны хоёр талын мод) нь өгүүлэгдэхүүн, 长得 (ургаж) дараа нь зэрэг заасан 真高 (үнэхээр өндөр) орж 街道两边的树长得真高 болно.'),
  ('aabd15ed-62dc-465c-8709-bf40be06ce3f'::uuid, 'Бүтэц: 请+[үйл үг]+[тодотгол+нэр үг]+[үйл үг2]+[объект]. 请用 (хэрэглээд өгнө үү) эхэнд, дараа нь хэрэглэх зүйл 黑板上的词 (самбар дээрх үг), эцэст нь 写一个句子 (нэг өгүүлбэр бич) орж 请用黑板上的词写一个句子 болно.'),
  ('ceb71b74-84e7-4e8b-99c4-68514ffa04f9'::uuid, 'Цоорхойн ард 化 байгаа бөгөөд өмнө нь 茶 (цай) байна. wén дуудлагатай, 文化 (соёл) гэсэн үг үүсгэдэг 文 үсгийг хийвэл 茶文化 (цайны соёл) гэсэн зөв нэр үг гарна. Тиймээс 文 зөв.'),
  ('6c66b823-6a84-43d5-821e-9a88f412ee71'::uuid, 'Цоорхойн ард 司要举行会议 (компани хурал хийнэ) гэж байгаа тул 公司 (компани) гэдэг үг бүрдэх ёстой. gōng дуудлагатай 公 үсэг оруулбал 公司要举行会议 (Компани хурал хийх гэж байна) болно.'),
  ('b5901180-c543-43f3-aaeb-4bae8fbf47a5'::uuid, '对大家的___来表示欢迎 (бүгдийн ямар нэг зүйлд угтан авалт илэрхийлэх) гэсэн өгүүлбэрт 到来 (ирэлт) гэдэг нэр үг таарна. dào дуудлагатай 到 үсэг нэмбэл 对大家的到来表示欢迎 (Бүгдийг ирсэнд нь угтан авъя) болно.'),
  ('3b400a0a-14a2-48a6-a0b5-4ac0972593cb'::uuid, '___校旁边有条河 (... сургуулийн хажууд гол бий) гэсэн өгүүлбэрт 学校 (сургууль) гэдэг үг таарах ёстой. Xué дуудлагатай 学 үсэг нэмбэл 学校旁边有条河 (Сургуулийн хажууд гол байна) болно.'),
  ('ae78c441-38f1-446a-94a4-11a5a47e4572'::uuid, '买点儿苹果___西瓜 (алим ... тарвас арай нь ав) гэсэн өгүүлбэрт хоёр зүйлийг холбох 和 (ба, бас) холбоос үг хэрэгтэй. hé дуудлагатай 和 үсэг оруулбал 买点儿苹果和西瓜 (Жаахан алим, тарвас ав) болно.'),
  ('24d9dc0e-a991-4c37-b682-5ebd66dc39b9'::uuid, '姐，你要看的那个电视节目已经开始了 (Эгч ээ, чиний үзэх гэсэн нэвтрүүлэг эхэлчихлээ) гэсэн дуудлагад F 好，我洗完头发就过去 (За, толгойгоо угаачихаад очъё) хариу нь зохимжтой — толгой угааж дуусаад очно гэсэн шууд хариулт. Бусад сонголтууд огт өөр сэдэвтэй.'),
  ('ddbb65d4-cf80-4009-923f-3699a45544ca'::uuid, '孩子现在不太愿意跟我说话，怎么办 (Хүүхэд надтай ярихыг хүсэхгүй байна, яах вэ) гэсэн асуултад C 你该多花点儿时间跟儿子在一起，多跟他聊聊天儿 (Хүүтэйгээ илүү цаг өнгөрөөж, илүү ярилц) зөвлөгөө өгч байгаа тул тохирно.'),
  ('d2fbf686-6bb7-48b5-a6c6-7eea2b108af5'::uuid, '穿绿裙子的那个小朋友真可爱 (ногоон юбка өмссөн тэр хүүхэд үнэхээр хөөрхөн) гэсний дараа A 听说她还很聪明，每次考试都是年级第一 (сонсоход тэр ухаантай ч, шалгалт болгонд ангиараа тэргүүлдэг гэнэ) гэж тухайн хүүхдийн тухай үргэлжлүүлж магтаж байгаа тул зохимжтой.'),
  ('95fa87c0-e090-4138-bb74-733349a8f67c'::uuid, '你先坐下来喝杯饮料，休息一下 (Эхлээд суугаад ундаа уугаад амарцгаая) гэснийг B 跳了两个小时的舞，真累啊 (2 цаг бүжиглээд үнэхээр ядарлаа) гэдэгтэй холбож болно — ядарсан учраас амрахыг санал болгож байна.'),
  ('be1ad08d-4b61-45a3-9c09-22faec3141e6'::uuid, '旧的问题还没解决，新的问题又来了 (хуучин асуудал шийдэгдээгүй байтал шинэ асуудал дахиад гарч ирлээ) гэсэнд D 公司最近怎么了？事情一件接着一件 (Компанид сүүлийн үед юу болж байна? Асуудал дараалан гарч байна) хариу тохирно — ижил утгаар үргэлжилж байна.'),
  ('b5026304-ba25-4411-ba64-8c2139c26aac'::uuid, '准备好了吗？笑一笑，我要开始照了 (Бэлэн үү? Инээмсэглээрэй, зураг авч эхэлье) гэсэн зааврыг C 大家离得近一点儿，个子矮的同学站前面 (Бүгд ойрхон зогсоорой, намхан оюутнууд урдаа зогсоорой) зургийн өмнөх заавартай холбож болно.'),
  ('91cb37ff-8de2-40c4-95d8-5684e2f14612'::uuid, '好，但听完了就要睡觉啊 (За, гэхдээ сонссоны дараа унтах ёстой) гэсэн хариу B 妈妈，你给我讲个故事吧 (Ээж ээ, надад үлгэр ярьж өгөөч) гэсэн хүсэлтийн дараа зохистой хариу болно.'),
  ('5012ec0a-ce93-4640-b7d5-af4d70696cd4'::uuid, '王阿姨每天都很忙 (Ван эгч өдөр бүр их завгүй) гэсэн шалтгааныг D 除了工作学习，她还要照顾孩子 (Ажил сургуулиас гадна тэр хүүхдээ асрах ёстой) гэдэг тайлбарлаж байгаа тул зохимжтой.'),
  ('18bd5af2-e00b-495b-896c-5b78eddad413'::uuid, '看上去很不错，相信她一定会喜欢的 (харахад сайхан харагдаж байна, тэр заавал таалагдана байх) гэсний өмнө A 这是我昨天去商店给妹妹买的生日礼物 (энэ бол би дүүдээ өчигдөр дэлгүүрээс худалдаж авсан төрсөн өдрийн бэлэг) гэж бэлгээ танилцуулж байгаа тул холбогдоно.'),
  ('3f7b3794-9c88-469d-9e5e-7657a34a7a20'::uuid, '那我们下午去超市吧 (тэгвэл бид өдийн шөнө дэлгүүр рүү явцгаая) гэсний шалтгаан нь E 冰箱里只有牛奶和鸡蛋，没其他吃的了 (хөргөгчинд зөвхөн сүү, өндөг л байна, өөр идэх юм алга) — идэх зүйл дуусаад дэлгүүрлэх хэрэгтэй болсныг харуулна.'),
  ('c5f047f2-8609-4f49-ac63-489fccecd050'::uuid, '得哭了起来 (уйлж эхэлтэл) гэсэн үр дүнг заасан хэсгийн өмнө сэтгэл хөдлөлийн шинж тэмдэг нэр орох ёстой. F 难过 (гунигтай, харамсалтай) нь «难过得哭了起来» (гунигтай улмаас уйлж эхэллээ) гэсэн зөв утга өгнө. Бусад нь дайвар үг эсвэл нэр үг тул тохирохгүй.'),
  ('ca032b7c-ea68-4ec5-ad3b-bb86649ab7a7'::uuid, '问题不像你想的那么（   ） (асуудал чиний бодсон шиг тийм ... биш) гэсэнд асуудлыг тодорхойлох тэмдэг нэр хэрэгтэй. B 简单 (энгийн) орж «问题不像你想的那么简单» (асуудал бодсон шигээ энгийн биш) гэсэн зөв утга гарна.'),
  ('dc461f87-4029-481c-aeab-25bfacfa8ad3'::uuid, '飞机马上就要（   ）了 (онгоц удахгүй ...) гэсэн 马上就要...了 (удахгүй ... болно) хэв маягт үйл үг орно. D 起飞 (нисэх) орж «飞机马上就要起飞了» (онгоц удахгүй нисэх гэж байна) болно.'),
  ('b4d59da3-a816-49f7-8e76-874982e659a4'::uuid, '人们（   ）在生病以后，才认识到健康有多么重要 (хүмүүс ... өвдсөний дараа л эрүүл мэндийн ач холбогдлыг ойлгодог) гэсэнд A 总是 (үргэлж) орж давтагдах шинж чанарыг илэрхийлнэ.'),
  ('50b8eca7-8d4c-4d59-a09d-cfc94556e470'::uuid, '你（   ）要来啊 (чи ... ирэх ёстой шүү) гэсэн хатуу урилгад C 一定 (заавал) тохирно — «你一定要来啊» (Чи заавал ирээрэй!) гэсэн утга гарна.'),
  ('ed8e9c26-bb4b-4300-8f75-f11c72a284b1'::uuid, '少了一（   ）筷子 (нэг ... сав хутга дутуу байна) гэсэнд 筷子 (сав хутга)-ны тоолох үг B 双 (хос) хэрэгтэй — «少了一双筷子» (нэг хос сав хутга дутуу байна) болно.'),
  ('c0f970a6-27ed-4024-83f9-eb6f990027af'::uuid, '回去后要（   ）复习 (гэртээ харьсны дараа ... давтах хэрэгтэй) гэсэнд F 记得 (санаж байх, мартахгүй байх) тохирно — «记得复习» (давтахаа бүү март) гэсэн зөвлөгөө болно.'),
  ('20313fe3-29ab-453b-83e3-45565654ed77'::uuid, '你（   ）试试 (чи ... оролдоод үз) гэсэнд зөвлөж байгаа өнгө аяс тул C 应该 (ёстой) тохирно — «你应该试试» (Чи оролдож үзэх ёстой) болно.'),
  ('ebfb7976-8e17-4554-b0ab-5fd74614b952'::uuid, '我（   ）明天早上去北京西站买火车票 (би ... маргааш өглөө Бээжингийн Баруун буудал руу тасалбар авахаар явна) гэсэнд төлөвлөгөө заасан A 打算 (төлөвлөж байна) тохирно.'),
  ('76bb99d3-ca94-4376-8505-5990dd938bb3'::uuid, '我们是去爬山，你怎么穿（   ）啊 (бид уул авирах гэж байхад чи яагаад ... өмссөн юм бэ) гэсэн шүүмжлэлд уулын өмсгөлд тохирохгүй E 皮鞋 (арьсан гутал) тохирно — B хариулт «忘记换了» (солихоо мартчихав) гэдэгтэй нийцнэ.'),
  ('1753b428-5c49-4b9c-aa16-080b420dab05'::uuid, 'Эх бичвэрт «它有好几百年的历史了» (энэ нь хэдэн зуун жилийн түүхтэй) гэж шууд хэлсэн тул A «历史较长» (түүх харьцангуй урт) зөв. 漂亮 (үзэсгэлэнтэй) эсвэл дотор нь будаа байгаа тухай юу ч дурдаагүй.'),
  ('c15bbb8c-b9d6-4b72-a6c4-fe91485dae46'::uuid, '«船票比火车票便宜很多» (хөлөгний тийз галт тэрэгнийхээс хамаагүй хямд) гэдгээс эсрэгээр галт тэрэгний тийз үнэтэй гэдгийг ойлгоно, тул C «火车票更贵» зөв. Тэд хугацаа урт байсан ч (6 цаг удаан) хямд тул хөлөг сонгосон юм.'),
  ('de20f2f2-8bb5-4d45-9290-57097292c7f1'::uuid, '«我下午要出去，不在公司» (би өдөр орой гарна, компанид байхгүй) гэж шууд хэлсэн тул A «不在办公室» зөв. Биеийн үзлэг, тоглоомын тухай юу ч дурдаагүй.'),
  ('1cd67dff-8be8-4606-91f3-bc86fd65bb33'::uuid, '«重要的、着急的事情用红笔画出来，…先做什么、后做什么» гэснээс эхлээд гол чухал зүйлээ хийхийг зөвлөж байгаа тул C «要先做重要的事» зөв.'),
  ('3fc5ffcf-a887-459c-a132-8665c6449e55'::uuid, '«南京现在比我们这儿热多了，都可以穿裙子了» (Нанжин манайхаас хамаагүй халуун, хормойн даашинз ч өмсдөг боллоо) гэдгээс манайх Нанжингаас хүйтэн, хормойн даашинз өмсөж болохооргүй байгааг ойлгоно — тул B «还不能穿裙子» зөв.'),
  ('780e769c-788d-46f5-87b9-379c0b2f6a53'::uuid, '«她的汉语水平提高了不少» (түүний хятад хэлний түвшин мэдэгдэхүйц дээшилжээ) гэж шууд хэлсэн тул C «中文水平提高了» зөв. Дуу дуулах, спортын мэдээ үзэх тухай юу ч дурдаагүй.'),
  ('9fdae06f-13c6-450f-b4dd-ec6c8ade8989'::uuid, '«如果工作是你自己感兴趣的，再累也是快乐的» (хэрэв ажил чиний сонирхсон зүйл байвал ямар ч ядраад байсан баяр хөөртэй) гэж хэлсэн нь тэр өөрийн ажилдаа дуртайг харуулж байна, тул C «喜欢自己的工作» зөв.'),
  ('513849fd-4a2f-4345-a4c3-142f35bee802'::uuid, '«女儿担心它声音太大，晚上会影响我和她爸爸休息» (охин чимээ ихтэй тул эцэг эхийнхээ амралтад нөлөөлнө гэж санаа зовжээ) гэдгээс охин эцэг эхдээ санаа тавьдгийг мэднэ, тул B «关心爸妈» зөв.'),
  ('d62a840c-1e39-49e4-8f53-7a78561ec24a'::uuid, '«这个地方的茶特别有名» (энэ газрын цай онцгой алдартай) гэж шууд хэлсэн тул A «茶很有名» зөв. Шар айраг, цай уухыг дургүйцэх тухай юу ч дурдаагүй.'),
  ('a40f64eb-667e-4f23-880d-3a5cef52c9b8'::uuid, '«出国留学…是一种锻炼» (гадаадад суралцах нь нэг төрлийн бэхжилт/дадлагажилт) гэж шууд хэлсэн, дараа нь өөрийгөө асрах, шинэ асуудал шийдэхийг сурдгийг нэмж тайлбарласан тул B «能锻炼人» зөв.'),
  ('3feabf9d-e767-44de-bf21-a26ffb4d0b3c'::uuid, 'Өгүүлбэрийн бүтэц: өгүүлэгдэхүүн «他» + үйл үг «学习» + зэрэглэлийн үг «特别» + чанарын нэр үг «努力». Тиймээс «他学习特别努力» (тэр маш хичээнгүй суралцдаг) гэж эрэмбэлнэ. «特别» нь «努力»-ийн өмнө орж хэр их хичээнгүйг тодотгоно.'),
  ('40fa471f-039b-4b16-b21a-c3a49d59ff7b'::uuid, 'Өгүүлэгдэхүүн «你» + хүсэл сонирхол заасан туслах үйл үг «想» + гол үйл үг «吃» + асуух тодотголт нэр үг «哪种面包». Тиймээс «你想吃哪种面包？» (чи ямар нэртэй талх идэхийг хүсэж байна вэ) болно.'),
  ('36365fd8-9eb0-4a3f-a9d6-45d61c336c1a'::uuid, 'Өгүүлэгдэхүүн «你的脸» + үгүйсгэх дэд үг «还没» (одоохондоо ...аагүй) + үйл үг+үр дүнгийн нэмэлт «洗干净» (угааж цэвэрлэх). «还没» нь үйл үгийн өмнө орно, тиймээс «你的脸还没洗干净» (чиний нүүр одоохондоо угаагдаж цэвэрлэгдээгүй байна) болно.'),
  ('a152730f-6ca4-4db6-a936-d4dd86e48f99'::uuid, 'Өгүүлэгдэхүүн «他的成绩» + дэд үг «一直» (үргэлж) + холбох үйл үг «是» + нэрлэсэн хэсэг «我们班最好的» (манай ангийнх нь хамгийн сайн нь). Тиймээс «他的成绩一直是我们班最好的» (түүний дүн үргэлж манай ангид хамгийн сайн байсан) болно.'),
  ('71d42ec9-72c4-455f-990d-f19cb36518ac'::uuid, 'Өгүүлэгдэхүүн «那位老人» + дэд үг «已经» (аль хэдийн) + тоо хэмжээ «107岁» + өөрчлөлт заасан үгийн төгсгөлийн «了». Тиймээс «那位老人已经107岁了» (тэр өвгөн аль хэдийн 107 настай болжээ) болно.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('91a231ec-9a44-4ce8-9e9f-2c5a40f446a2'::uuid, 'Гэдэсний өмнөх «季» ханзтай хослуулбал 季节 [jìjié] (улирал) гэсэн үг болно — өгүүлбэр тарвасны амтыг улирлаас хамааруулж байгаа тул зохимжтой. Тиймээс дутуу ханз нь «节» [jié].'),
  ('cf8f140d-be36-4f62-b8b2-28a3fa48abde'::uuid, '«太阳下山了» (нар жаргах)-ын эсрэг тал болгож «___亮就出来了» гэж байгаа тул 月亮 [yuèliang] (сар) гэсэн үг бүрдэнэ. Тиймээс дутуу ханз нь «月» [yuè].'),
  ('1ae4871e-dffa-43a4-a384-f0844e6241d1'::uuid, 'Худалдан авагчид үлдэгдэл мөнгө «6角5分钱»-ийг өгч буй тул 找 [zhǎo] (хариулт мөнгө өгөх) гэсэн үйл үг таарна — 找您钱 (танд хариулт өгье). Тиймээс дутуу ханз нь «找».'),
  ('c7d0910c-d27f-48c1-aa29-160d74471374'::uuid, '«大熊猫» (гигант панда) амьтныг тоолоход хэрэглэдэг тоолуур үг нь 只 [zhī]. Тиймээс дутуу ханз нь «只».'),
  ('37524830-fb22-4541-92eb-8160767021b5'::uuid, '«知道___己想要什么» гэдэгт 自己 [zìjǐ] (өөрөө) гэсэн үг бүрдэнэ — өөрийгөө юу хүсдэгээ мэдэх гэсэн утга. Тиймээс дутуу ханз нь «自» [zì].'),
  ('52e5e560-75be-4524-8455-cfe5c59b1a61'::uuid, '«月亮又大又（ ）» (сар том бас ... ) гэдэгт сарны дүрсийг тодорхойлох B «圆» (дугуй) тохирно — 又大又圆 (том бас дугуй). 拉 (татах), 完全 (бүрэн), 坚持 (тэвчих), 重点 (гол цэг), 饺子 (бууз) нь нэр үг эсвэл өөр утгатай тул тохирохгүй.'),
  ('daa9cf9c-138d-4ef0-9791-331c9c005cce'::uuid, '«全家人在一起包（ ）» гэдэгт 包饺子 (бууз хийх) нь шинэ жил тэмдэглэхэд гэр бүлээрээ хийдэг тогтмол хэллэг тул F «饺子» зөв.'),
  ('f1a6ef8e-d0b3-4edb-9301-8debee798d50'::uuid, '«他（ ）有能力做好这件事，但他没有认真去做» гэдэгт «чадвартай байсан ч хичээгээгүй» гэсэн эсрэг санааг илэрхийлэхийн тулд C «完全» (бүрэн) тохирно — 完全有能力 (бүрэн чадвартай байсан).'),
  ('f589e696-12fb-4826-8d46-ff880e6c64da'::uuid, '«四五个大人手（ ）手才能抱住» гэдэгт 手拉手 (гар гараа барих) тогтсон хэллэг тул A «拉» (татах) зөв — олон хүн гараараа холбогдож модыг тэврэх дүрслэл.'),
  ('0a5a9ed7-ee2d-4d4e-a91f-9a79b9934b48'::uuid, '«讲话应先讲（ ）» гэдэгт эхлээд гол чухал зүйлээ хэлэх нь ойлголцлыг хурдасгах тул E «重点» (гол цэг) зөв.'),
  ('7a71eeef-673e-4527-99ff-a3a6b7704912'::uuid, '«我现在在（ ）处» гэдэгт онгоцны буудал дахь байршил заах тул D «入口» (орох хаалга) зөв — 入口处 (орох хаалганы дэргэд).'),
  ('a263cb02-5099-49fc-a788-77eb609f13d9'::uuid, '«我（ ）好了就发给你» гэдэгт зургаа эмхлэн бэлдсэний дараа илгээх санааг илэрхийлэх тул F «整理» (эмхлэн засах) зөв.'),
  ('36b06054-f814-41f4-a3c2-c8c471f90bdf'::uuid, '«身高没（ ）一米二» гэдэгт өндрийн хязгаарыг хэлж буй тул B «超过» (хэтрэх) зөв — 没超过一米二 (нэг метр хорин см-ээс хэтрэхгүй).'),
  ('be874843-5503-4204-a510-edbdc0a265e3'::uuid, '«看（ ）你对这里很熟悉» гэдэгт 看样子 (харахад ... шиг байна) тогтсон хэллэг тул A «样子» зөв.'),
  ('9d95213e-3540-49f8-b1cf-85c3b0df508a'::uuid, '«大夫说不（ ）» гэдэгт зөвхөн арьс хуссан тул эмчийн дүгнэлт хүнд биш гэсэн санаа илэрхийлэх тул E «严重» (ноцтой) зөв.'),
  ('8dcd4546-2bf3-41cf-985d-7b1ec9be81d4'::uuid, 'C «机会来了，就该主动去试一试» (боломж ирвэл идэвхтэй оролдох ёстой) эхэлж санааг гаргана, B «即使失败了也没关系» (бүтэлгүйтсэн ч зөвшөөрнө) нь «即使...也» холбоосоор үргэлжлэн эрсдэлийг хүлээн зөвшөөрч, A «至少我们努力过» (ядаж бид хичээсэн) дүгнэлт болно. Тиймээс CBA дараалал зөв.'),
  ('768b8feb-bd56-4e85-b35e-33c4c0219272'::uuid, 'B «钱虽然能买到很多东西» (мөнгөөр олон юм авч болно ч) эхэлж, A «但世界上还有很多是钱买不到、也换不来的» «虽然...但» холбоосоор эсрэг санаа гаргаж, C «例如生命、爱情、友谊和时间» жишээ өгч төгсгөнө. Тиймээс BAC дараалал зөв.'),
  ('dceed034-285c-46dc-8cf6-673e8aa25268'::uuid, 'A «北方秋天很干燥，你刚来» (хойд нутгийн намар хуурай, чи саяхан ирсэн) шалтгаан, B «觉得不适应很正常» (дасаагүй мэдрэх нь хэвийн) үр дагавар, C «每天多喝水，习惯了就不会那么难受了» (өдөр бүр их ус уувал дассаны дараа тэр их зовлонгүй болно) зөвлөгөө болж дараална. Тиймээс ABC зөв.'),
  ('77c1410c-6b26-4588-8f88-2717bd8b40df'::uuid, 'B «课本上的知识并不能解决我们遇到的所有问题» (сурах бичгийн мэдлэг бүх асуудлыг шийдэхгүй) эхэлж, A «实际上，很多问题的答案都可以从生活中找到» («实际上» гэдэг холбох үгээр үргэлжилж) шийдлийг амьдралаас олдгийг хэлж, C «但这需要我们用眼睛去发现，用心去总结» («但» -аар нөхцөл нэмж) төгсгөнө. Тиймээс BAC зөв.'),
  ('14c6c33f-6d4d-4e61-9994-fc0e854e32e3'::uuid, 'B «我提高汉语水平的方法就是坚持看中文报纸» (миний хятад хэлээ дээшлүүлэх арга бол тогтмол сонин унших) эхэлж, C «这样不但能学到很多新的词语» («这样不但» холбоосоор давуу талыг нэрлэж), A «还能扩大知识面» («还» -аар нэмэлт давуу тал нэмж) төгсгөнө. Тиймээс BCA зөв.'),
  ('9fdc9fdd-b681-419f-a63c-85d48c387aee'::uuid, 'C «别看小黄个子不高，人也瘦» (Сяохуаныг намхан туранхай гэж бүү бод) эхэлж, B «力气却大得很» («却» эсрэг холбоосоор хүчтэй болохыг заана), A «这些家具很多都是他帮忙抬上来的» нотолгоо болж төгсгөнө. Тиймээс CBA зөв.'),
  ('f34503e6-2d61-4861-931f-a355853688aa'::uuid, 'B «昨晚19时南京市突然下起了大雨» (өчигдөр орой 19 цагт Нанжинд гэнэт хүчтэй бороо орсон) шалтгаан, A «飞往该市的好几趟航班» (тэр хот руу нисэх хэдэн нислэг) объект, C «都不得不推迟起飞» (бүгд хойшлохоос өөр аргагүй болсон) үр дагавар. Тиймээс BAC зөв.'),
  ('23c180a4-789c-4232-81c0-a089aeb59043'::uuid, 'A «我家离北京很近» (миний гэр Бээжингээс ойрхон) эхэлж, C «只有100多公里，开车的话大约一个小时就到了» тодруулж, B «所以周末和节假日我一般都会回家» («所以» дүгнэлт) төгсгөнө. Тиймээс ACB зөв.'),
  ('72311676-1d17-4ba7-80b2-65dceb9e6121'::uuid, 'B «两个人既然决定共同生活» («既然» нөхцөл) эхэлж, C «那么，只有浪漫和新鲜感是不够的» («那么» дараагийн санаа), A «懂得互相信任和尊重才是最重要的» дүгнэлт болж төгсгөнө. Тиймээс BCA зөв.'),
  ('eceae41e-94e4-4552-9972-56acdba91377'::uuid, 'C «爸爸说我小时候特别害怕打针» (аав хэлэхдээ би багадаа тариа их айдаг байсан) эхэлж, A «一看见医生就哭，他怎么都没想到» тодруулж, B «我长大后竟然会成为一名护士» гайхмаар үр дүнг хэлж төгсгөнө. Тиймээс CAB зөв.'),
  ('183bbb2c-d7d5-4a07-871a-88221badf9c9'::uuid, 'Эх бичвэрт «别忘了，他身上的优点更值得我们去发现、去学习» (бүү март, түүний давуу тал илүү анзаарч, сурах ёстой зүйл) гэж байгаа тул хариулт D «看到别人的优点» (бусдын давуу талыг харах). A (тэвчээртэй байх), B (шүүмжлэлийг хүлээн авах), C (уучлахыг сурах) нь эх бичвэрт байхгүй санаа.'),
  ('4a8ba6ad-cd5c-4f75-bd58-d57963e4c3d3'::uuid, '«在高温的夏季，森林内的温度会比周围低3到5℃» (халуун зуны улиралд ойн доторх температур эргэн тойрноос 3-5 хэм бага) гэсэн тул зун ой юу хийдгийг асуухад A «降低气温» (агаарын температурыг бууруулах) зөв. Салхины чиглэл, бороо, чийг тухай яриагүй тул B, C, D таарахгүй.'),
  ('1d881e33-b7ad-42ca-935a-c140bc17221c'::uuid, '«选择职业时，我们首先应该对自己有清楚的认识» (мэргэжил сонгохдоо эхлээд өөрийгөө тодорхой мэдэх ёстой) гэдэг тул D «先认清自己» (эхлээд өөрийгөө таних) зөв. Судалгаа хийх, суурь тавих, дүгнэлт гаргах тухай биш, харин өөрийгөө таних тухай өгүүлж байна.'),
  ('fd8e5338-c69c-4bea-af26-3bde2937d1e0'::uuid, '«真正健康的减肥方法应该是多锻炼» (жинхэнэ эрүүл турах арга бол илүү дасгал хийх) гэснээр A «多运动» (илүү их хөдөлгөөн хийх) зөв. Хоолны хэмжээг хязгаарлах (B), зогсох (C), тоглоом тоглох (D) нь эх бичвэртэй холбоогүй.'),
  ('7bbc9c0c-908f-4287-afd6-0b321970a3ee'::uuid, 'Энэ бол байр түрээслэгч эсвэл зуучлагчийн үг бөгөөд «房租也不贵，您要不要再考虑一下» (түрээс ч хямд, дахин бодоод үзэхгүй юу) гэж байгаа тул Жан ноён C «在找房子» (байр хайж байгаа) гэдэг нь тодорхой. Мэхлэгдсэн, ойролцоо амьдардаг, зар үзэж байгаа гэсэн санаа эх бичвэрт байхгүй.'),
  ('1f1c7efc-d178-4376-bc8d-ff0f6c3ca19f'::uuid, '«在小城市生活就会轻松许多» (жижиг хотод амьдрах нь илүү хөнгөн) гэдгээс D «生活压力小» (амьдралын дарамт бага) зөв. Аюулгүй байдал, орлого, ажлын байрны тухай биш, харин амьдралын дарамтын тухай өгүүлж байна.'),
  ('a8ec38c7-b479-461e-a2c0-6a2f8ce2291d'::uuid, '«最好的办法就是早点儿把它做完» (хамгийн сайн арга бол түүнийг эрт дуусгах) гэснээс C «早点儿完成» (эрт дуусгах) зөв. Хүнд даалгах (B), тусламж хайх (A), сүүлд үлдээх (D) нь эх бичвэрийн зөвлөгөөтэй яг эсрэг эсвэл хамааралгүй.'),
  ('57410a39-1c67-4c04-89a7-923bbc3f0626'::uuid, '«如果你每天用100字把自己的生活写下来» (өдөр бүр 100 үгээр амьдралаа бичвэл) гэж хэлж байгаа тул D «记下自己的生活» (өөрийн амьдралыг тэмдэглэх) зөв. Үнэнч байх, даруу байх, давтлага хийх тухай биш, харин өдөр тутмын амьдралаа бичихийг зөвлөж байна.'),
  ('ada414f6-1809-41b4-9c14-a4b1b190cba9'::uuid, '«音乐表达的感情有时更容易让人听懂» (хөгжмөөр илэрхийлсэн мэдрэмж заримдаа илүү амархан ойлгогддог) гэснээс C «更容易理解» (илүү амархан ойлгогдоно) зөв. Нарийн төвөгтэй, гунигтай, дурсамжтай гэсэн санаа биш, харин ойлгомжтой байдлын тухай өгүүлж байна.'),
  ('2aea68e5-2f3d-4a96-8c17-73807af0c197'::uuid, '«有时候也不能完全相信经验，而应该根据不同的情况选择不同的方法» (заримдаа туршлагад бүрэн итгэж болохгүй, өөр өөр нөхцөл байдалд өөр өөр аргыг сонгох ёстой) гэснээс D «不一定适合现在» (одоог тэр бүр тохирохгүй байж болно) зөв. Туршлага үнэн зөв, үнэлэх ёстой гэдэг санааг эх бичвэр няцааж байна.'),
  ('23d40bb2-3cf2-41e3-a367-1c296315ae87'::uuid, '«一方面是想让各国学生更好地了解中国，另一方面是想为学生们提供互相交流和学习的机会» (нэг талаас Хятадыг сайн ойлгуулах, нөгөө талаас харилцан суралцах боломж олгох) гэдгээс D «相互增加了解» (харилцан ойлголтоо нэмэгдүүлэх) зөв нэгтгэсэн хариулт. Ханз таних, кампус танилцах, итгэл нэмэгдүүлэх тухай биш.'),
  ('a4db18cc-1927-4c8d-9d88-6bf106613fee'::uuid, '«尤其是赛前那个星期，他每天都会把全部动作练习好几遍» (тэмцээний өмнөх долоо хоногт өдөр бүр бүх хөдөлгөөнөө хэд хэдэн удаа дасгалждаг) гэдгээс A «更努力» (илүү хичээнгүй) зөв. Догдолсон, санаа зовсон, дасгалаа зогсоосон гэсэн санаа эх бичвэрт байхгүй.'),
  ('cd9e60d6-b586-4e1b-9930-03846c1d6c44'::uuid, 'Асуулт яагаад дароо уучлалт гуйдгийг асуухад эх бичвэрт «否则可能引起误会，让人以为你不友好» (эс тэгвэл буруу ойлголт үүсгэж, найрсаг бус гэж бодогдоно) гэж шалтгааныг тодорхой хэлсэн тул A «减少误会» (буруу ойлголтыг бууруулах) зөв. Өрөвдөх, магтаал авах гэсэн санаа биш.'),
  ('79ffd07b-0aed-42c3-8be7-1e61aa0bf942'::uuid, '«老师看她手脚也大，身体其他条件也很符合游泳运动员的要求» (багш нь гар хөл нь том, биеийн бусад шинж чанар нь усанд сэлэгчийн шаардлагад тохирч байгааг харсан) гэснээс D «身体条件好» (биеийн физик шинж сайн) зөв. Ухаалаг байдал, гүйдэг хурд, шагнал авсан тухай өгүүлээгүй.'),
  ('1e5f18ae-2e84-47d9-82ea-33598de3c1f6'::uuid, '«当一条路走不通时，我们可以换另外一条试试» (нэг зам явахгүй бол өөр замаар оролдож болно) гэдгээс B «试试别的路» (өөр зам оролдох) зөв. Газрын зураг харах, орон нутгийн хүнээс асуух, найздаа утасдах тухай эх бичвэрт байхгүй.'),
  ('6303ac43-7d87-4189-b431-26a06fff0ef7'::uuid, '«只要我们不放弃努力，总会找到一条合适的路，通往成功的目的地» (хичээл зүтгэлээ орхихгүй бол амжилтад хүрэх зам олдоно) гэсэн нь C «成功需要坚持» (амжилтад тэвчээр тууштай байдал хэрэгтэй) гэсэн ерөнхий санааг илэрхийлж байна. A, B, D нь тодорхой дэлгэрэнгүй зөвлөгөө боловч эх бичвэрийн үндсэн санаа биш.'),
  ('7d7d7e73-a6fb-434d-a758-6263b63956f0'::uuid, '«购书满100元即可获得日记本一个» (100 юанийн ном авбал өдрийн тэмдэглэл дэвтэр авна) гэж шууд бичсэн тул B «日记本» зөв. Толь бичиг нь 200 юанид (A), бусад хариулт эх бичвэрт байхгүй.'),
  ('2af9745a-272d-4240-a3b1-294b481d483c'::uuid, '«部分图书还有打折活动，其中，小说7.5折» (зарим номд хямдрал бий, тэдгээрийн дунд роман 7.5 хямдралтай) гэдгээс C «有些书打折» (зарим ном хямдралтай) зөв. A «小说半价» (роман хагас үнэтэй) буруу — 7.5折 нь хагас (5折) биш. Амралт, борлуулалт сайн байгаа тухай өгүүлээгүй.'),
  ('c77c1285-12ec-4efa-a6a7-cae6a951b2b7'::uuid, 'Цагаан бохирдлыг багасгах тухай «买菜时自备购物袋，少用塑料袋，减少白色污染» (ногоо авахдаа өөрийн сав авч, хуванцар уут бага хэрэглэх) гэж шууд заасан тул C «少用塑料袋» зөв. Уур зогсоох, ус хэмнэх, зориулалтын сав ашиглах тухай өгүүлбэрт бус, тусдаа зүйлд хамаарна.'),
  ('a2399b47-a195-493a-919b-a87838824f1d'::uuid, 'Эх бичвэр нь цахилгаан, тээвэр, хуванцар уутны талаар өдөр тутмын жижиг үйлдлээр «保护地球环境» (дэлхийн орчныг хамгаалах) хийхийг ярьж байгаа тул ерөнхий сэдэв нь B «环境保护» (байгаль орчны хамгаалал). Нийгмийн хариуцлага, эдийн засгийн хөгжил тухайн эх бичвэрийн гол сэдэв биш.'),
  ('7efd82c2-32c2-454e-a932-d85662678f7c'::uuid, '«你最好» (чи ... хийвэл дээр) гэсэн зөвлөмжийн эхлэл дараа нь «重新» (дахин) гэсэн дайвар үг үйл үгийн өмнө орж, «换» (солих) үйл үг, эцэст нь «一个密码» (нэг нууц үг) тэмдэг нэр орно: 你最好重新换一个密码。'),
  ('f474dc6c-db4b-42ad-9b7e-52be6a514119'::uuid, 'Газрыг заасан «医院里» (эмнэлэгт) өгүүлбэрийн эхэнд, дараа нь «不允许» (зөвшөөрдөггүй) нөхцөл, эцэст нь «抽烟» (тамхи татах) үйл үг орно: 医院里不允许抽烟。'),
  ('63aee296-6734-42ad-bae2-2c6c881f4bba'::uuid, 'Өгүүлэгдэхүүн «我» (би) эхэнд, дараа нь харьцуулах эзэмшлийн бүтэц «跟你的看法» (чиний үзэлтэй), эцэст нь тодотгол үйл үг «差不多» (адилхан гэсэн): 我跟你的看法差不多。'),
  ('d30c2a08-a1bc-40c1-a795-ca1edb841c78'::uuid, '«这儿究竟» (эндээс яг юу болов) гэсэн асуултын эхлэл, дараа нь «发生了» (болсон) үйл үг, эцэст нь «什么事情» (ямар явдал) асуух үг орно: 这儿究竟发生了什么事情？'),
  ('2e012cce-ad29-4117-baee-289edec699b8'::uuid, 'Өгүүлэгдэхүүн «他» (тэр) эхэнд, дараа нь «出生在» (төрсөн газар) байршил заах үйл үг, эцэст нь «一个美丽的小城市» (нэгэн үзэсгэлэнт жижиг хот): 他出生在一个美丽的小城市。'),
  ('207e8c19-0f1d-4bda-9c15-6955a2dc6366'::uuid, '把 хэлц: «姐姐» (эгч) өгүүлэгдэхүүн, «把房间» (өрөөг) 把-ийн объект, «收拾得很整齐» (цэвэрлэж эмх цэгцтэй болгосон) нь үйл үг + нөхцөлт нэмэлт: 姐姐把房间收拾得很整齐。'),
  ('91edc3bc-5155-4f39-96d1-7c9160048e5a'::uuid, '由...负责 хэлц: «这次调查» (энэ судалгаа) сэдэв, «是由李经理» (Ли менежерээр хийгддэг) хариуцагч, эцэст нь «负责的» тодотгол: 这次调查是由李经理负责的。'),
  ('bd4982f4-60e1-4c5a-9f12-6c491bdf053e'::uuid, 'Тоо хэмжээ заасан «大概有三分之二的人» (гуравны хоёр орчим хүн) эхэнд, дараа нь өгүүлэхүүн үйлдэл «反对这样做» (ингэж хийхийг эсэргүүцдэг): 大概有三分之二的人反对这样做。'),
  ('ee9cc455-8215-4f3b-8ad4-4fc1f7056054'::uuid, 'Өгүүлэгдэхүүн «学校» (сургууль) эхэнд, ирээдүйн цаг заах «将» дайвар үг, «组织大家» (бүгдийг зохион байгуулах) үйл үг, эцэст нь зорилго заах «去参观长城» (Их хэрмийг үзэхээр очих): 学校将组织大家去参观长城。'),
  ('ec78f2a7-736c-4862-bb36-08a3f8da3e88'::uuid, '«对...的理解和支持» хэлц: «非常感谢您» (танд маш их баярлалаа) эхэнд, дараа нь «对我们工作的» тодотгол, эцэст нь объект «理解和支持» (ойлголц, дэмжлэг): 非常感谢您对我们工作的理解和支持。'),
  ('ae749d43-2b2c-4234-9460-8697fedb8153'::uuid, '«小李很活泼» (Сяо Ли идэвхтэй хөгжилтэй) гэдэгтэй холбож, цоорхойд орох нь орчны байдлыг тодорхойлох тэмдэг нэр байх ёстой тул F «热闹» (шуугиантай, хөгжилтэй) зөв. Бусад нь дайвар үг (往往), нэр үг (意见), үйл үг (坚持, 出差) тул тохирохгүй.'),
  ('9ba7c567-5692-45fa-87f2-4d2f9d9ae2bb'::uuid, '«不是（）的要求都接受» (бүх л шаардлагыг хүлээн зөвшөөрдөггүй) гэдэгт «要求» (шаардлага)-ыг тодотгох нэр үг хэрэгтэй тул A «所有» (бүх) зөв. 往往, 坚持 зэрэг үйл үг, дайвар үг «要求»-ийг тодотгож чадахгүй.'),
  ('33d4b7b7-66fc-4e89-a244-cfcfc58ab23f'::uuid, '«去北京（）» (Бээжинд ...-аар очих) гэдэгт ажлын шалтгаанаар явахыг илэрхийлэх үйл үг хэрэгтэй тул C «出差» (томилолтоор явах) зөв. Дараагийн өгүүлбэр «我们改天再见吧» (өдрөө сольж уулзая) нь энэ таамгийг баталж байна.'),
  ('aeaabd50-f1a3-4daf-941f-c7c2ad38b237'::uuid, '«最危险的地方（）也是最安全的地方» (хамгийн аюултай газар ... хамгийн аюулгүй газар байдаг) гэсэн зөрчилтэй үнэнийг илэрхийлэхэд «ихэвчлэн» гэсэн утгатай дайвар үг хэрэгтэй тул B «往往» зөв.'),
  ('22d20078-7459-48cd-9343-461583fa5fef'::uuid, '«大家在会上提的（）» (бүгдийн уулзалт дээр гаргасан ...) гэдэгт цуглуулах зүйл нь санал, үзэл бодол байх ёстой тул E «意见» (санал) зөв. «整理出来» (эмхэтгэн гаргах) гэдэг үйл үгтэй хамт хэрэглэгддэг.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('4bcfe489-f0dd-4ee4-9ac4-bdb9dc638f26'::uuid, '«你的动作还不太（）» (чиний хөдөлгөөн одоохондоо тийм ч ... биш) гэдэгт хөдөлгөөний чанарыг үнэлэх тэмдэг нэр хэрэгтэй тул E «标准» (стандарт, зөв) зөв. «右腿再抬高一点儿» (баруун хөлөө бага зэрэг өндөр өргөх) нь засварлах зөвлөгөө тул хөдөлгөөн бүрэн стандарт биш гэдгийг харуулж байна.'),
  ('0c042d37-6f26-44a8-9254-fc781470bfdb'::uuid, '«能及时（）到会场吗» (цагтаа хурлын танхимд ...-ж очих уу) гэдэгт «очих» үйл үгийн өмнө орж «яаравчлан» гэсэн утгатай үйл үг хэрэгтэй тул A «赶» (яаравчлан очих) зөв.'),
  ('b226ad93-c2f4-49d4-bd44-7beb0386d21a'::uuid, '«我才填到第二（）» (би дөнгөж хоёр дахь ...-д хүрч бөглөж байна) гэдэгт бөглөх маягтын нэгжийг заах нэр үг хэрэгтэй тул B «页» (хуудас) зөв.'),
  ('2a273d06-0d33-45f2-8a02-3bc66342cd61'::uuid, '«（）好的» (маш сайн) гэдэгт тэмдэг нэрийг эрчимжүүлэх дайвар үг хэрэгтэй тул F «挺» (нэлээд, их) зөв — «挺好的» нь ярианы хэлц.'),
  ('e9270dce-5e1e-4836-b517-632b1041c778'::uuid, '«电话怎么一直（）呢» (утас яагаад байнга ...) гэдэгт утасны шугамын байдлыг заах үг хэрэгтэй тул D «占线» (шугам завгүй) зөв. Дараагийн өгүүлбэр «是不是电话没放好» (утсаа зөв тавиагүй байх нь) энэ утгыг баталж байна.'),
  ('3541509d-2603-4859-acd8-da4980b1f6ac'::uuid, 'Эхлээд ерөнхий баримт «这个学期我一共选了5门课» (энэ улиралд нийт 5 хичээл сонгосон) өгүүлж, дараа нь «在所有这些课中» (энэ бүх хичээлийн дунд) гэж хамрах хүрээг нарийсгаж, эцэст нь «我最喜欢的是中国音乐史» (хамгийн дуртай нь Хятадын хөгжмийн түүх) гэж дүгнэдэг тул дараалал BAC.'),
  ('86ca119e-e0b6-43fc-b645-a061ea89e59b'::uuid, '«对于中国人来说» (хятадуудын хувьд) гэсэн сэдвийн танилцуулгаар эхэлж, «春节是一年之中最重要的节日» (шинэ жил хамгийн чухал баяр) гэж баримт өгч, эцэст нь «到那时人们会举行各种各样的迎新年活动» (тэр үед янз бүрийн арга хэмжээ хийдэг) гэж нэмэлт мэдээлэл өгдөг тул дараалал ACB.'),
  ('03e95c87-16c6-4c48-bc58-99b2be853528'::uuid, '«很多人以为老虎不会游泳» (олон хүн бар усанд сэлж чаддаггүй гэж боддог) гэж алдаатай ойлголтоор эхэлж, «但科学家发现，老虎其实是游泳高手» (харин эрдэмтэд бар үнэндээ сэлэгч гэдгийг олж мэдсэн) гэж эсрэгцүүлж, эцэст нь «它们甚至能游数十公里那么远» (тэд бүр хэдэн арван км сэлж чаддаг) гэж нэмэлт баримт өгдөг тул дараалал CAB.'),
  ('d21709bf-e2b2-4bd0-8fab-525618da5882'::uuid, '«我办了新闻手机报服务» (би мэдээллийн утасны үйлчилгээ захиалсан) гэж үйлдлээр эхэлж, «每天都能收到经济、社会和国际等方面的新闻短信» (өдөр бүр эдийн засаг, нийгэм, олон улсын мэдээ авдаг) гэж үр дүнг тайлбарлаж, эцэст нь «这样我就可以及时了解国内外发生的大事了» (ингэснээр дотоод, гадаадын том үйл явдлыг цаг тухайд нь мэдэж чадна) гэж дүгнэдэг тул дараалал BCA.'),
  ('f7d1c6b4-84d9-4b0e-bd17-ebae378b6331'::uuid, '«每个人都会死去» (хүн бүр үхэх болно) гэсэн ерөнхий үнэнээр эхэлж, «但不是每个人都真正活过» (харин хүн бүр жинхэнээсээ амьдарч байгаагүй) гэж харьцуулж, эцэст нь энэ хос өгүүлбэрийг «《勇敢的心》 кинонд байдаг» гэж эх сурвалжийг нь заадаг тул дараалал ACB.'),
  ('c951c091-7b8e-4ac5-9a8c-5467f2378840'::uuid, '«不光...还要...» бүтэц: «学习时，不光要知道答案是什么» (сурахдаа зөвхөн хариултыг мэдэхээс гадна) гэж эхэлж, «还要弄清楚答案究竟是怎么得来的» (хариулт хэрхэн гарсныг ойлгох хэрэгтэй) гэж нэмж, эцэст нь «只有这样，才能把问题真正弄懂» (ийм байж л асуудлыг жинхэнэ утгаар нь ойлгож чадна) гэж дүгнэдэг тул дараалал ACB.'),
  ('5e6ef4e4-1a07-4e2a-b435-831ff243c532'::uuid, '«这次招聘会本来是由小李负责的» (энэ ажил горилуулах уулзалтыг эхэндээ Сяо Ли хариуцаж байсан) гэж эхэлж, «由于他突然生病住院了» (тэр гэнэт өвдөж эмнэлэгт хэвтсэн учраас) гэж шалтгаан хэлж, эцэст нь «后来就交给我来做了» (дараа нь надад даалгасан) гэж үр дагаврыг хэлдэг тул дараалал CBA.'),
  ('17d8cfee-c70c-4a8d-a202-4c620477bb20'::uuid, '«那条小吃街在西安很有名，很多人都说» (тэр хачир хоолны гудамж Сиань хотод их алдартай, олон хүн ярьдаг) гэж танилцуулгаар эхэлж, «要是去了西安而没有去那儿尝尝小吃» (Сианьд очоод тэнд очиж амтлаагүй бол) нөхцөл, эцэст нь «就不能说自己到过西安» (Сианьд очсон гэж хэлж чадахгүй) дүгнэлт ирдэг тул дараалал BAC.'),
  ('2dd29bd5-798c-4593-a5e5-c88793427558'::uuid, '«抱歉，小姐，您的包不能带入馆内» (уучлаарай, таны цүнхийг тайланд оруулж болохгүй) гэж эхэлж, «入口处有专门存包的地方» (орох хаалганд цүнх хадгалах тусгай газар бий) гэж тайлбарлаж, эцэст нь «您可以把包放在那儿» (та цүнхээ тэнд тавьж болно) гэж зөвлөдөг тул дараалал CBA.'),
  ('f5d69c47-ac43-4068-acf3-64a844690525'::uuid, '«太阳有地球的130万倍那么大» (нар дэлхийгээс 1.3 сая дахин том) гэж эхэлж, «而月球只有地球的1/49» (харин сар дэлхийн 1/49 хэмжээтэй) гэж харьцуулж, эцэст нь «但我们从地球上看却感觉它们大小差不多» (гэвч дэлхийгээс харахад тэдгээр ижил хэмжээтэй мэт санагддаг) гэж эсрэгцүүлдэг тул дараалал BAC.'),
  ('7d46535f-90aa-429d-81a6-d16d311af924'::uuid, 'Эх бичвэрт «一定要试着让自己冷静下来» (заавал өөрийгөө тайвшруулахыг хичээ), «别让紧张的心情影响了自己» (сандарсан сэтгэл хөдлөлдөө бүү автагд) гэж байгаа тул ярилцлагад орохдоо B «别太紧张» (хэт бүү сандар) гэдэг нь зөв. A, C, D-ийн тухай эх бичвэрт огт дурдаагүй.'),
  ('6c769b03-3b80-4405-b4db-16b7a2413e34'::uuid, '«但我觉得我的语法还不太好，需要多学习» (гэхдээ дүрэм маань сайн биш, илүү сурах хэрэгтэй гэж боддог) гэдэг өгүүлбэрээс тэр юу хүсэж байгааг мэднэ. Тиймээс C «多学语法» (дүрмээ илүү сур) зөв. Ярианы харилцаа сайн гэдгийг өөрөө хэлсэн тул A, B, D тохирохгүй.'),
  ('e502eef8-efa4-460d-9494-636a73a4d1f8'::uuid, '«关键是要勇敢地去做，只有去做，一切才有可能» (гол нь зоригтой хийх явдал, зөвхөн хийж эхэлбэл л бүх зүйл боломжтой болно) гэдэг өгүүлбэр A «敢于开始» (эхлэхээс бүү ай) гэсэн хариултыг баталж байна. Урьдчилж хэт их бодох нь буруу гэж бичсэн тул B, C, D нь эх бичвэртэй нийцэхгүй.'),
  ('fdce7ba8-b398-4072-a637-7eb39116555b'::uuid, '«想找一个空气新鲜、安静的地方好好放松一下» (агаар сэргэг, тайван газар олж амрахыг хүсдэг) гэдэг нь B «环境不错» (орчин сайхан) гэсэн хариулттай тохирно. Тээвэр тухтай гэж бичсэн ч «堵车бага» эсвэл «худалдан авалт тухтай» гэж хэлээгүй тул C, D буруу.'),
  ('67d781e7-812f-482d-8fa0-48dbc5c88da4'::uuid, '«云南是中国少数民族最多的省» (Юньнань бол Хятадад цөөнх үндэстэн хамгийн олонтой муж) гэж шууд бичсэн тул C «少数民族多» (цөөнх үндэстэн олон) зөв. Байгаль үзэсгэлэнтэй эсвэл газарзүйн байрлалын тухай эх бичвэрт байхгүй тул A, D зохиомол.'),
  ('cd687067-7ceb-409a-ab66-f90c67e299a6'::uuid, '«如果顾客完全不需要它，我们就很难把它卖出去» (хэрэглэгчид огт хэрэггүй бол зарахад хэцүү) гэдэг нь чанар, үнээс гадна B «自己的需要» (өөрийн хэрэгцээ) чухал гэдгийг харуулж байна. Сэтгэл санааны холбоо, худалдагчийн санаа зэргийг эх бичвэрт дурдаагүй тул A, C буруу.'),
  ('24a740cc-47b5-4efb-92f6-328249bae791'::uuid, '«他们能更清楚地看到我们的缺点和错误» (найзууд маань бидний дутагдал, алдааг илүү тод хардаг) гэдэг өгүүлбэрээс A «发现缺点» (дутагдлаа олох) зөв гэдэг нь ойлгогдоно. Нөхөрлөл олох, шүүн тунгаах чадвар нэмэгдэх тухай дурдаагүй тул B, C тохирохгүй.'),
  ('2217869b-92b7-44ce-ac8b-16ab79e540ca'::uuid, 'Эхний өгүүлбэр «地球上的气候真有趣» (дэлхийн уур амьсгал үнэхээр сонирхолтой) гэж эхэлж, дараа нь жишээ өгч байгаа тул B «很有意思» (сонирхолтой) зөв. Бохирдол, өөрчлөлтгүй байдлын тухай биш, харин ялгаа их байгааг үзүүлж байгаа тул C, D буруу.'),
  ('9fdb5074-f62d-4937-b7d3-a468ae4b2b4b'::uuid, '«困难只是暂时的» (бэрхшээл түр зуурынх) гэдэг өгүүлбэр «风雨» (шуурга, бороо) гэдгийг зүйрлэлээр «бэрхшээл» гэж ойлгуулж байна. Тиймээс A «困难» зөв. Дурсамж, санаа зовнил, зорилго гэдэг утга эх бичвэрт байхгүй.'),
  ('f993918c-8cf3-404d-9812-9b037bbefdc8'::uuid, '«可能是上次比赛失败，受了影响» (өнгөрсөн тэмцээнд ялагдсанаас болж сэтгэл санаа муудсан байх) гэсэн тул D «上次比赛输了» (өмнөх тэмцээндээ хожигдсон) зөв. Турсан, тамирлаа орхисон гэх мэт зүйлийг эх бичвэрт дурдаагүй тул A, B, C зохиомол.'),
  ('5775ed58-fdec-4f5e-a4be-a7b4c86dcb7c'::uuid, '«旅行能丰富你的经历» (аялал туршлагыг чинь баяжуулдаг) гэж эхэлж, аяллын ач холбогдлыг тайлбарласан тул A «旅游的好处» (аяллын давуу тал) зөв. Ярианы урлаг, ном унших тухай биш тул B, C буруу.'),
  ('f39cec71-2a60-4cf8-9021-1106d79b1a82'::uuid, '«表扬对孩子的作用要比批评大得多» (магтаал шүүмжлэлээс хамаагүй их үр дүнтэй) гэж бичсэн тул C «多表扬» (олон удаа магтах) зөв. Шүүмжлэл ихэсгэх нь эсрэг санаа тул B буруу, тэвчээртэй байх, чанга шаардлага тавих тухай биш.'),
  ('9a9d0910-edc2-4e26-bbf5-2c118eaa813e'::uuid, '«每天早上都把当天计划要干的事情写在纸上» (өглөө бүр өдрийн ажлын төлөвлөгөөгөө цаасан дээр бичдэг) гэдэг нь C «做好计划» (төлөвлөгөө сайн гаргах) гэсэн хариулттай тохирно. Радио сонсох, дасгал хийх, имэйл илгээх тухай огт дурдаагүй.'),
  ('4b871a31-7ba7-404a-a6eb-2ae72e6b196b'::uuid, '«其实并不是茶，而是一种用中药做成的饮料» (энэ нь цай биш, харин уламжлалт эмээр хийсэн ундаа) гэж тодорхой бичсэн тул B «是一种饮料» (нэг төрлийн ундаа) зөв. Амттай, дулаахан уухад илүү сайн гэх мэт зүйлийг эх бичвэрт огт бичээгүй тул A, C, D тохирохгүй.'),
  ('58fd8463-9da7-408d-9f25-713b4b99c1d6'::uuid, '«前20名学生» болон «后20名学生» гэж хоёр бүлэг оюутныг дурдсан тул нийлбэрээр B «共40名» (нийт 40 хүн) зөв. Тэдний зан төлөв, чихэр идэх дуртай эсэх, худал хэлсэн эсэх тухай эх бичвэрт байхгүй.'),
  ('060600fc-c22f-43e6-8f77-f5df3db5c590'::uuid, '«太多的东西容易让人无法选择» (хэт олон зүйл байвал сонголт хийхэд хэцүү болдог) гэж дүгнэсэн тул D «选择多不一定好» (сонголт олон байх нь үргэлж сайн биш) зөв. Хог хаягдал, менежментийн тухай биш, харин сонголтын тоог л өгүүлж байна.'),
  ('2cb834ba-fb88-47ad-8e95-2c22270b1b06'::uuid, '«还有几个地方需要改一下，比如一些大事的排列顺序等等» (заримыг засах хэрэгтэй, жишээ нь дараалал) гэж бичсэн тул D «有不准确之处» (буруу тохиолдох газар бий) зөв. Тайлан богино, дунд зэрэг, гол санаа дутсан гэж хэлээгүй тул A, B, C буруу.'),
  ('2b748956-95b4-4565-91df-7fcfd0060082'::uuid, '«你改完再重新发我一份» (засаад дахин илгээ) гэдэг нь A «再改改» (дахин бага зэрэг засаарай) гэсэн хариулттай тохирно. Бүхэлд нь дахин бичих, үг цөөрүүлэх, хугацаанд нь дуусгах тухай хэлээгүй.'),
  ('7c5ad7e6-d7c8-4e06-af2e-cb9851c19c9b'::uuid, '«我既没车也没房子，钱也很少» (надад машин ч, байшин ч байхгүй, мөнгө ч бага) гэж залуу өөрөө хэлж байгаа тул A «很穷» (ядуу) зөв. Ухаалаг, аз жаргалтай, чадварлаг гэдгийг эсрэгээр эх бичвэр эхэнд харуулаагүй.'),
  ('468fb65a-3a05-4f4a-a43d-3bbdee8fb5b3'::uuid, '«健康» болон «年轻»-ийг 100万-аар ч зарахгүй гэдгийг ойлгуулснаар мөнгөнөөс үнэтэй зүйл байдгийг өгүүлж байгаа тул D «钱不是最重要的» (мөнгө хамгийн чухал зүйл биш) зөв. Хуурч мэхлэх, хэмнэлт хийх тухай биш.'),
  ('6d25a796-8e05-475c-83a5-963e81305643'::uuid, 'Өгүүлбэрийн бүтэц нь өгүүлэгдэхүүн 电梯 (лифт) + цагийн дэд үг 已经 (аль хэдийн) + боломжийн үг 可以 + байдлын дэд үг 正常 (хэвийн) + үйл үг+了 使用了 (ашиглаж эхэлсэн) дараалалтай байна. Тиймээс зөв өгүүлбэр «电梯已经可以正常使用了» болно.'),
  ('46b1e500-f726-4da8-bcd0-b2b00aad8cb7'::uuid, '欢迎 (тавтай морил) гэдэг үг өгүүлбэрийн эхэнд, дараа нь харьцах этгээд 您, дэд үг 再次 (дахин) нь үйл үг 乘坐-ийн өмнө орж, эцэст нь object 我们的航班 (манай нислэг) ирнэ. Тиймээс «欢迎您再次乘坐我们的航班» гэж дараалуулна.'),
  ('be81e8d9-7bca-4ec1-8219-253bcfe7d523'::uuid, 'Өгүүлэгдэхүүн 你们 эхэнд, дараа нь үр дүнгийн нөхцөл бүхий үйл үг 商量出 (ярилцаж гаргах), тухайн зүйлийн object 解决问题的方法 (асуудал шийдэх арга), эцэст нь асуултын 了吗 ирнэ. Тиймээс «你们商量出解决问题的方法了吗» гэсэн зөв дараалалтай.'),
  ('d338951f-b177-459f-bca5-3d150525783b'::uuid, '第一印象往往 (эхний сэтгэгдэл ихэвчлэн) гэсэн өгүүлэгдэхүүн хэсгийн ард 很难 (маш хэцүү) гэсэн зэрэглэлийн дэд үг, эцэст нь үйл үг 改变 (өөрчлөгдөх) ирнэ. Тиймээс «第一印象往往很难改变» болно.'),
  ('dd17dec8-a435-4b06-a92d-8f77303d32f2'::uuid, '这个消息 (энэ мэдээ) өгүүлэгдэхүүн эхэнд, 真是 (үнэхээр) дараа нь ирж, 太...了 бүтэц 太让人激动了 (хүмүүсийг үнэхээр догдлуулсан) хэсэг эцэст ирнэ. Тиймээс «这个消息真是太让人激动了» гэж дараалуулна.'),
  ('546c7052-dee1-456c-a148-1ec64a6875ae'::uuid, '他们俩 (тэд хоёр) өгүүлэгдэхүүн, 有 (байх) үйл үг, 许多共同语言 (олон нийтлэг хэл, санаа) object болж эцэст ирнэ. Тиймээс «他们俩有许多共同语言» гэсэн зөв өгүүлбэр гарна.'),
  ('6711163c-7bb6-411e-8d7c-d4bf29a337e2'::uuid, '这场比赛 (энэ тэмцээн) өгүүлэгдэхүүн, 赢得 (ялж авсан) үйл үг + 得 нөхцөлийн бүтэц, эцэст нь зэрэглэлийн нөхцөл 非常漂亮 (маш сайхан) ирнэ. Тиймээс «这场比赛赢得非常漂亮» гэж дараалуулна.'),
  ('3b604843-0bf1-4fbb-bc05-35764e11c7db'::uuid, '任何事情的发生 (ямар ч зүйлийн тохиолдол) нь өгүүлэгдэхүүн, 都是...有原因的 нь 是...的 бүтэцтэй тодотгол хэсэг болж эцэст ирнэ. Тиймээс «任何事情的发生都是有原因的» гэсэн зөв өгүүлбэр гарна.'),
  ('8f81f131-abfd-4475-846b-941cd3ea8b2a'::uuid, '互联网 (интернет) өгүүлэгдэхүүн, 拉近了 (ойртуулсан) үр дүнгийн нөхцөлт үйл үг, 人与人之间的距离 (хүмүүсийн хоорондох зай) object болж эцэст ирнэ. Тиймээс «互联网拉近了人与人之间的距离» гэж дараалуулна.'),
  ('987223c6-8918-4182-ab8d-fbab88eeb1af'::uuid, '请 (гуйя) эхэнд, дараа нь 把 бүтэц 把这篇文章 (энэ өгүүллэгийг), үр дүнгийн нөхцөлт үйл үг 翻译成 (орчуулаад ... болгох), эцэст нь 中文 (хятад хэл рүү) ирнэ. Тиймээс «请把这篇文章翻译成中文» гэсэн зөв бүтэц гарна.'),
  ('2feeb3e4-ebed-416c-86a2-21112dd57214'::uuid, 'Цоорхойн ард 压力 (дарамт) гэсэн үг ирж байгаа тул «缓解压力» (дарамтыг сааруулах) гэсэн тогтмол хэллэгт тохирох A 缓解 зөв. 消失 (алга болох), 消灭 (устгах) нь дарамттай хамт хэрэглэгддэггүй тул тохирохгүй.'),
  ('7b4bc332-6931-4a98-8b40-0c7e671b0ba3'::uuid, 'Өмнөх өгүүлбэрт буруу ойлголтыг дурдаад, дараа нь жинхэнэ шийдлийг тайлбарлаж байгаа тул 47-р цоорхойд C 正确 (зөв) орж «正确的做法» (зөв арга) болно. 真实 (жинхэнэ), 合法 (хуулийн дагуу) нь энд утга оноогүй.'),
  ('00847226-c24a-44a8-86b3-33127f57c4bc'::uuid, '把不好的（ ）宣泄出来 (муу зүйлээ гаргаж тавих) гэдэгт гаргах ЗҮЙЛ хэрэгтэй бөгөөд A 情绪 (сэтгэл хөдлөл) хамгийн тохиромжтой. 语气 (аяс), 观点 (үзэл бодол), 表情 (нүүрний хувиралт) нь 宣泄 (гаргаж тавих) үйлийн object болж чаддаггүй.'),
  ('30360dba-25fd-45e2-8c6a-7be098e52f57'::uuid, '«这就49你把水从1℃加热到99℃» гэдэг нь дараагийн зүйрлэлийг танилцуулж байгаа тул харьцуулалт хийхэд хэрэглэдэг C 好像 (яг л ...шиг) зөв. 例如 (жишээлбэл), 不如 (илүү дэмий), 据说 (гэж сонссон) нь энэ бүтцэд тохирохгүй.'),
  ('f037cc71-8da9-4b9b-b49f-f8186ddc4651'::uuid, '1℃ нэмэгдэхэд ус шингэнээс хий болж бүрэн шинж чанараа өөрчилдгийг тайлбарлаж байгаа тул A 彻底 (бүрэн, эцсийн байдлаар) зөв. 反复 (давтан), 陆续 (дараалан) нь энэ гэнэтийн, бүрэн өөрчлөлтийг илэрхийлдэггүй.'),
  ('a0f32401-85e2-476e-bd23-b696dc0635ec'::uuid, 'Дараагийн өгүүлбэрт «也不是人生的绝处» (амьдралын эцсийн зам ч биш) гэж байгаа тул утга нь ойролцоо D «失败并不是最终的定论» (бүтэлгүйтэл эцсийн шийдвэр биш) хамгийн зохимжтой. A, B, C нь энэ өмнөх усны жишээний санаатай холбогдохгүй.'),
  ('e6907cd3-98b9-499b-af71-c2ca9bcf807d'::uuid, '热情 (хичээл зүтгэл), 信心 (итгэл) хоёрын хамт эерэг чанарыг жагсааж байгаа тул B 勇气 (зориг) хамгийн тохиромжтой. 感想 (сэтгэгдэл), 风格 (хэв маяг), 行为 (үйлдэл) нь энэ жагсаалтад ижил төрлийн зүйл биш.'),
  ('95eaf0b6-5c8a-4cb4-b895-ae890b9d825d'::uuid, '球场上53没有穿一、二、三号球衣 (тоглогчид 1, 2, 3 дугаартай өмсдөггүй гэдгийг огт байхгүй гэдгийг онцолж) байгаа тул B 根本 (огт, ерөөсөө) зөв. 凡是 (бүгд), 格外 (онцгойлон), 总算 (эцэст нь) нь энэ үгүйсгэлийг онцлон илэрхийлдэггүй.'),
  ('1d13a449-884a-4443-bf50-72662df83b87'::uuid, '54比赛规定 (тэмцээний журмын дагуу) гэсэн утга дараа нь дүрмийг дэлгэрэнгүй тайлбарлаж байгаа тул D 按照 (дагуу) зөв. 对于 (тухайд), 通过 (дамжуулан), 自从 (тэр цагаас хойш) нь дүрмийг дагаж мөрдөх гэсэн утгыг өгдөггүй.'),
  ('089a3db1-62a4-4436-8650-6c3e264f4257'::uuid, 'Шүүгч хурууны тоогоор дохио өгдгийг өмнө нь тайлбарласан тул 55-р цоорхойд C 号码 (дугаар) орж «队员的号码» (тоглогчийн дугаар) болно. 形象 (дүр төрх), 位置 (байрлал), 形势 (нөхцөл байдал) нь дугаартай холбоогүй.'),
  ('b5db3892-8fb0-432e-90b1-84ad97f7069f'::uuid, 'Шүүгч хурууны дохиогоор тоо илэрхийлдэг тул 1, 2, 3 дугаартай тоглогч байвал шүүгчийн дохиотой хольж андуурах магадлалтай. Тиймээс C «就很容易引起误会» (амархан ойлголцгүйтэл үүсгэнэ) зөв. A, B, D нь энэ логиктой холбоогүй.'),
  ('af0f9eb5-205f-4acc-9dd7-e9299a00d696'::uuid, '武士 (дайчин) хааныг дагаж тулалдаанд оролцсон гэдгийг өгүүлж байгаа тул A 陪伴 (хамт явах, дагалдах) зөв. 协调 (зохицуулах), 组织 (зохион байгуулах), 执行 (гүйцэтгэх) нь хааныг дагаж тулалдсан гэсэн утгад тохирохгүй.'),
  ('4dbdcf24-c4ec-4721-86bf-9934325c333c'::uuid, 'Хаан үг дуугарахгүйгээр дараагийн хүнээс дахин ижил асуулт асуусан тул B «国王没有表态» (хаан ямар ч байр суурь илэрхийлээгүй) зөв. Хожим «国王仍旧没有说话» (хаан бас дуугарсангүй) гэж давтагдаж байгаа нь үүнийг баталж байна.'),
  ('bc99406b-7f2d-42d1-8651-b2062ce9129a'::uuid, '武士甚至没有走近 (дайчин ойртож ч үзээгүй) шууд хариулсан гэдгийг тайлбарлаж байгаа тул A 直接 (шууд, нэн даруй) зөв. 正式 (албан ёсоор), 紧急 (яаралтай), 明显 (тодорхой) нь энэ утгад тохирохгүй.'),
  ('7a105bca-3bd1-406f-a2e6-10c5bad283cd'::uuid, 'Хаан баяртай байж, багшийг «只有你才是合适的人选» (зөвхөн чи л тохирох хүн) гэж эерэгээр үнэлж байгаа тул D 称赞 (магтах) зөв. 命令 (тушаах), 答应 (зөвшөөрөх), 欣赏 (таашаах, гэхдээ дараагийн шууд яриаг нэвтрүүлэхэд тохирохгүй) нь энд тохирохгүй.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('b8bbc8be-68ef-46c1-959b-4ee627f77de9'::uuid, 'эх бичвэрт «如今，围棋在亚太地区广泛流行，并逐渐受到世界各地人们的欢迎» (одоо гоо тоглоом Ази номхон далайн бүсэд өргөн дэлгэрч, дэлхийн өнцөг булан бүрд улам их хүмүүст таалагдаж байна) гэж байгаа тул D «нөлөөллийн хүрээ нь тэлж байна» гэдэг үнэн. A (дүрэм төвөгтэй), B (4 хүнд зориулагдсан), C (1000 гаруй жилийн түүхтэй) тухай эх бичвэрт тодорхой байхгүй.'),
  ('e00996ca-6f18-4e41-adaf-392f8691eaed'::uuid, 'эх бичвэрт «能有效地改善心、肺功能，调节心理和精神状态» (зүрх, уушгины үйл ажиллагааг сайжруулж, сэтгэл зүй, оюун санааны байдлыг зохицуулдаг) гэсэн тул C «биед болон сэтгэлд ашигтай» гэдэг зөв. Мөн «强度低» (эрч хүч бага) гэсэн тул A (эрч хүч их) буруу.'),
  ('447abc2c-8cf5-489f-9f44-47bb81ed8709'::uuid, 'эх бичвэрт «一个懂得幽默的人知道如何调节气氛，他会让紧张严肃的谈话变得轻松愉快» (хошин шогийг мэддэг хүн уур амьсгалыг хэрхэн зохицуулахаа мэддэг тул хурц ярианыг хөнгөн, хөгжилтэй болгодог) гэсэн тул C «хошигнол мэддэг хүн уур амьсгал сэргээхийг мэддэг» гэдэг зөв.'),
  ('fc805a8f-ac25-4752-a239-7ef1b78038e1'::uuid, 'эх бичвэрт «遗忘了一些不愿记得或者想要逃避的人或事» (санахыг хүсэхгүй буюу зайлсхийхийг хүсдэг хүн, явдлаа мартдаг) гэж тодорхой заасан тул D зөв. A, B, C-д дурдсан (түгээмэл өвчин, тархинд ихээхэн хор хөнөөлтэй, эмчлэх боломжгүй гэх) зүйл эх бичвэрт байхгүй.'),
  ('4d2dfadd-d160-44b7-9e8e-9c2dae120be7'::uuid, '商人 хэлэхдээ «经验来自无数错误的判断» (туршлага нь тоо томшгүй буруу шийдвэрээс бий болдог), «没有错误的铺垫，谁也无法攀上成功的巅峰» (алдаагүйгээр амжилтын оргилд хэн ч гарч чадахгүй) гэсэн тул B «амжилт алдаанаас тусгаарлагдахгүй» гэдэг зөв.'),
  ('322f5cad-9565-4010-9fc3-c613c183be98'::uuid, 'эх бичвэрт «齐鲁就成了山东的代称» (齐鲁 гэдэг нь Шаньдун мужийн өөр нэр болсон) гэж эртний Ци, Лу улсын нэрнээс гаралтай хэмээн тайлбарласан тул A зөв. C буруу, учир нь эх бичвэрт «战国末年» (Тулалдах улсуудын үеийн эцэс) гэснийг сонголтод «初年» (эхэн үе) гэж буруу заажээ.'),
  ('f473bec1-1cd1-4ee8-bb62-3d69df129a05'::uuid, 'эх бичвэрт «夏眠是动物为了在缺少食物的季节生存下去...也是它们对炎热和干旱季节的一种适应» (зуны нойрсол бол хоол хүнс дутагдах, халуун ширүүн улирлаас амьд үлдэхийн тулд тохирсон дасан зохицол) гэсэн тул C зөв.'),
  ('9aca89a1-ffb2-4574-a3be-79d55b56fda9'::uuid, 'эх бичвэрт «第二类词是被俘后所写...成就远远超过前期» (олзлогдсоны дараа бичсэн хоёрдугаар төрлийн шүлэг нь өмнөх үеийнхээсээ хавьгүй ахисан амжилттай) гэсэн тул A «сүүлийн үеийн бүтээл нь илүү» гэдэг зөв.'),
  ('115baa0d-1f66-400d-89d5-b8e7ebac64e9'::uuid, 'эх бичвэрт «人在愤怒时智商是最低的...通常这个时候所做的决定，90%以上都是错误的» (уурлах үедээ хийсэн шийдвэрийн 90 гаруй хувь нь буруу байдаг) гэсэн тул B «уурласан үедээ амархан шийдвэр гаргаж болохгүй» гэдэг зөв.'),
  ('efe0889d-b776-40fd-be3c-252f9a6724dd'::uuid, 'эх бичвэрт «企业的发展需要团队...使团队发挥最大的效能» (аж ахуйн нэгжийн хөгжилд баг хамт олон хэрэгтэй, багийг үр ашигтай ажиллуулах ёстой) гэж голлон өгүүлсэн тул C «багийн бүтэц байгуулалт удирдлагад чухал» гэдэг зөв.'),
  ('795c81a5-6ace-409d-a8c6-8e5aafca67be'::uuid, '垂头丧气 гэдэг нь толгойгоо гудайлган, сэтгэл санаа унасан байдлыг илэрхийлдэг хэлц үг. Загасчин өдөржин загасгүй буцаж ирсэн учраас гунигтай, урам хугарсан байгаа тул D «сэтгэл санаа унасан» гэдэг зөв. A (өвчтэй), B (ядарсан), C (маш ноцтой) гэсэн утга агуулаагүй.'),
  ('0d2c19c7-9aa8-45c6-9470-84d8c8e78585'::uuid, 'эх бичвэрт хөрш «你织的网太小了，哪能捕到鱼？你得把网织得大一点儿» (чиний тор жижиг байна, том тор нэхэх хэрэгтэй) гэж зөвлөсөн тул B «том тор нэхэх» гэдэг зөв.'),
  ('ec1f2c16-f720-4058-9acb-b19f3d91952f'::uuid, 'сүүлийн хэсэгт «网中确实有很多鱼，这些鱼拼命地想挣开巨网...最后竟把渔夫的小船也拉翻了» (тор дотор олон загас байсан ч тэд оргож, завийг хүртэл нь хөмрүүлсэн) гэсэн тул эцэст нь загасчин загасгүй үлдсэн — C зөв.'),
  ('a1546f12-84af-4983-824c-f6456f07d350'::uuid, 'эх бичвэрт «渔夫这才明白网并非越大越好，贪得无厌往往会适得其反» (тор том байх тусам сайн биш, шунал их байх нь эсрэгээрээ муу үр дагавартай) гэж дүгнэсэн тул B «хүн хангалуун байхыг мэдэх ёстой» гэдэг зөв.'),
  ('c62673c4-1566-431f-8ef3-f4fd4bc5c3d8'::uuid, '狮子 хариулахдаа «大人物是不屑与低层次的人竞争的» (агуу хүн доод түвшний хүнтэй өрсөлдөхийг басамжилдаг) гэж тайлбарласан тул D «хулгантай тэмцэхийг басамжилсан» гэдэг зөв.'),
  ('07b2a216-0ded-46c2-8e62-d0a93f00e93e'::uuid, 'эх бичвэрт «与不是同一重量级的人争执不休，不仅会浪费时间...» (өөр түвшний хүнтэй маргалдвал цаг хугацаа дэмий үрэгддэг) гэж шууд өгүүлсэн тул A «цаг хугацаа дэмий үрэгдэнэ» гэдэг зөв.'),
  ('77302c3f-4e27-446f-bf63-c93ebfcd04ea'::uuid, 'эх бичвэрт «生活中最聪明的人往往是那些对无足轻重的事情无动于衷的人...这样的人善于把精力花在重要的事情上» гэсэн бөгөөд «这样的人» нь өмнөх өгүүлбэрт дурдсан «хамгийн ухаалаг хүн»-г заасан тул A зөв.'),
  ('f426581c-2b90-48a6-ae96-2e39dde56e4b'::uuid, 'эх бичвэрийн гол санаа нь «善于把精力花在重要的事情上，而将无关紧要的事情放在一边» (чухал зүйлд анхаарлаа төвлөрүүлж, хамаагүй зүйлийг орхих) гэсэн тул C «чухал зүйлд анхаарлаа хандуулах хэрэгтэй» гэдэг зөв.'),
  ('df9f03d0-5e71-4872-b1bc-860ade8eee6a'::uuid, 'эх бичвэрт «刚到河边，被打了耳光的那个人便一头栽进了河里» (гараа алгадуулсан хүн голд унасан) гэж шууд заасан тул C зөв.'),
  ('a33f5eea-4fc7-4005-860c-fb36a31573c2'::uuid, 'эх бичвэрт «把朋友的帮助刻在石头上，可以经得起时间的考验» (найзын тусыг чулуунд сийлж, цаг хугацааны шалгуурыг давуулна) гэж тайлбарласан тул C «найзын тусыг санахын тулд» гэдэг зөв.'),
  ('2c7124c7-7b11-4dc6-b928-96b4ab286888'::uuid, 'эх бичвэрт «因为是朋友，便把他的错误看成不可原谅，多了苛责» (найз учраас алдааг нь уучлашгүй гэж үзэн, илүү шаардлага тавьдаг) гэсэн тул A «найздаа хэт өндөр шаардлага тавих» гэдэг зөв.'),
  ('6d288812-2156-4c50-bc93-1f3d37fc846d'::uuid, 'эх бичвэр найз нөхдийн хоорондын гомдол, тусыг хэрхэн санах тухай өгүүлж, эцэст нь «忘记朋友的伤害，铭记朋友的关爱，珍惜身边的朋友» гэж дүгнэсэн тул B «найз нөхөдтэй хэрхэн харьцах вэ» гэдэг сэдэвтэй тохирч байна.'),
  ('014b7c32-a82c-4c4e-babe-4d823211422b'::uuid, 'эх бичвэрт «向别人借一个空瓶，去换第6瓶汽水» (хүнээс хоосон лонх зээлж аваад 6 дахь лонх ундаагаа авах) гэж тодорхой заасан тул D зөв.'),
  ('5f6e32d9-1417-4657-ab6c-1fe912990481'::uuid, 'эх бичвэрт «每个人都有很多闲置资源，它们或者被遗忘在角落里，或者被丢弃» (ашиглагдаагүй нөөц булан тохойд мартагдах эсвэл хаягддаг) гэсэн тул C «ихэвчлэн үл тоомсорлогддог» гэдэг зөв.'),
  ('26495624-5f9c-4be8-8646-c1bf8b29ed59'::uuid, 'эх бичвэрт «不是因为没有能力，而是因为他们没有转换思路，没有最大限度地利用已有的资源» (чадваргүйгээс биш, харин сэтгэлгээгээ өөрчилж, байгаа нөөцөө бүрэн ашиглаагүйгээс) гэж шууд тайлбарласан тул D зөв, A буруу.'),
  ('fe37ca8e-3eab-4e18-bdcf-3141be5c6191'::uuid, 'эх бичвэрийн гол санаа нь ашиглагдаагүй «空瓶» (хоосон лонх)-г бэлгэдэл болгон, нөөцийг дэмий үрэхгүй байхыг сануулж байгаа тул D «хоосон лонх-оо бүү дэмий үрэ» гэдэг гарчиг тохиромжтой.'),
  ('93836c76-2c6a-48b4-a04a-26f81ae07b78'::uuid, 'эх бичвэрт «给这个盘做一个特殊的标记——这个盘里的文件全都没用了，如果要储存新的文件可以存放到这个盘里来» (энэ дискэнд тусгай тэмдэг тавьж, шинэ файл хадгалж болно гэдгийг заадаг) гэсэн тул B «дискэнд сул зай байгааг илтгэнэ» гэдэг зөв.'),
  ('93eabe0f-5a8d-4db5-9063-c4ba9af8556f'::uuid, 'эх бичвэрт «数据恢复软件的作用就是让它们重新显示出来» (өгөгдөл сэргээх програм устгагдсан файлыг дахин харуулдаг) гэж шууд заасан тул C зөв.'),
  ('c5b7bc4f-8d34-4b7c-bade-e99138b4208f'::uuid, 'эх бичвэрт «电脑之所以这么做，是为了提高工作效率» (компьютер ингэж хийдгийн шалтгаан нь ажиллагааны хурдыг нэмэгдүүлэхийн тулд) гэж тодорхой заасан тул B зөв.'),
  ('48c721c4-be5e-48f6-a12e-f6b5468dcd95'::uuid, 'эх бичвэрт устгасан файл шинэ өгөгдлөөр дарагдаагүй л бол «这些被删除的文件就会永远留在原处» (устгасан файл байнга хуучин байрандаа үлддэг) гэсэн тул C «файл амархан бүрэн устдаггүй» гэдэг зөв.'),
  ('1eec5e44-2853-4093-822b-03d77b5612cb'::uuid, '«录取» (элсэлт) нь «结果» (үр дүн)-тэй нийлж эзэн гишүүн «录取结果» (элсэлтийн үр дүн) болно. «将在月底» (сарын эцэст) нь цаг заасан нөхцөл байдал, «公布» (зарлах) нь өгүүлэхүүн. Эцсийн бүтэц: 录取结果将在月底公布。(Элсэлтийн үр дүнг сарын эцэст зарлана.)'),
  ('e3e752c2-b6d2-47bb-a17a-47248461ba75'::uuid, '«他» эзэн гишүүн, «承认自己» (өөрийгөө хүлээн зөвшөөрөх) нь үндсэн өгүүлэхүүн бөгөөд дараа нь дэд өгүүлбэр орно: «缺乏自信» (итгэлгүй байх). Тул 他承认自己缺乏自信。(Тэр өөрийгөө итгэлгүй байгаагаа хүлээн зөвшөөрлөө.)'),
  ('6faff862-d335-4781-8f97-1805ad4608bf'::uuid, '«打折商品» (хямдралтай бараа) эзэн гишүүн, «不再» (дахин ... үгүй) сөрөг цагийн үг, «参加» (оролцох) өгүүлэхүүн, «其他优惠活动» (бусад хөнгөлөлтийн арга хэмжээ) нэмэгдэл гишүүн. Тул 打折商品不再参加其他优惠活动。(Хямдралтай бараа өөр хөнгөлөлтийн арга хэмжээнд дахин хамрагдахгүй.)'),
  ('d8557117-0316-47d2-8121-063eee4d7de9'::uuid, '«汽油的价格» (бензиний үнэ) эзэн гишүүн, «又» (дахин) цагийн үг, «上涨» (өсөх) өгүүлэхүүн, «了» өнгөрсөн цагийн нөхцөл. Тул 汽油的价格又上涨了。(Бензиний үнэ дахин өслөө.)'),
  ('02d6dbd4-4197-4d3c-b8a9-cd50e78ecc71'::uuid, '«这两家公司的待遇差别» (энэ хоёр компанийн нөхцөлийн ялгаа) эзэн гишүүн, «很大» (маш их) өгүүлэхүүн тэмдэг нэр. Тул 这两家公司的待遇差别很大。(Энэ хоёр компанийн ажлын нөхцөлийн ялгаа маш их байна.)'),
  ('47b4ae40-5d91-4277-b784-797296bd0a21'::uuid, '«那个小姑娘» (тэр охин) эзэн гишүүн, «非常» (маш их) зэрэг заасан үг, «孝顺» (эцэг эхдээ хайртай, тусархаг) тэмдэг нэр өгүүлэхүүн. Тул 那个小姑娘非常孝顺。(Тэр охин эцэг эхдээ маш их хайртай.)'),
  ('ef0a83d3-8e95-4529-bf2b-3541d76d4a83'::uuid, '«请» хүсэлт заасан үг, «在前台» (ресепшнд) газар заасан нөхцөл, «办理» (гүйцэтгэх) өгүүлэхүүн, «入住手续» (буудалд орох бүрдэл) нэмэгдэл гишүүн. Тул 请在前台办理入住手续。(Ресепшнд орох бүрдэл хэргээ гүйцэтгэнэ үү.)'),
  ('498d8a36-dd11-4dd3-ac4d-75839a249519'::uuid, '«这里» (энд) эзэн гишүүн, «还» (одоо ч гэсэн) цагийн үг, «保留着» (хадгалагдсаар байгаа) өгүүлэхүүн, «一些古老的» (зарим эртний) тодотгол, «风俗习惯» (заншил ёс) нэмэгдэл гишүүн. Тул 这里还保留着一些古老的风俗习惯。(Энд одоо ч гэсэн зарим эртний заншил хадгалагдсаар байна.)'),
  ('678c7b9d-6680-4c13-add0-70f16bf1a226'::uuid, 'Цоорхойн ард «成本低» (өртөг бага) гэж байгаа тул «纸币的[X]成本» нь эд зүйл хийх, үйлдвэрлэх утгатай үг шаардана. «制作» (үйлдвэрлэх, хийх) нь «制作成本» (үйлдвэрлэлийн өртөг) гэсэн байнгын хэллэг үүсгэдэг тул B зөв. «制定» хууль дүрэм тогтооход, «建立» байгууллага байгуулахад, «形成» аажмаар бүрэлдэхэд хэрэглэгддэг тул тохирохгүй.'),
  ('8dc09eda-ff7a-4649-a87c-6dca7d767729'::uuid, 'Цоорхойн ард «使用的货币形式» (хэрэглэдэг мөнгөний хэлбэр) гэж байгаа тул өмнөх нь «хэрэглэх»-ийг тодорхойлох дайвар үг байх ёстой. «普遍使用» (өргөн, түгээмэл хэрэглэх) нь байнгын хэллэг тул C зөв. «广大» ихэвчлэн хүмүүсийг тодорхойлдог, «普通» энгийн, «经典» сонгодог гэсэн утгатай тул тохирохгүй.'),
  ('a8488f95-3bbb-4a23-8cf0-04111a8fea7f'::uuid, 'Цоорхойн ард «于中国北宋时期的成都» (Хятадын Умард Сун улсын үеийн Ченду хотод) гэсэн газар цаг заасан тул «анх гарч ирсэн» гэсэн утгатай үг хэрэгтэй. «出现» (гарч ирэх) нь «出现于» гэсэн бүтэц үүсгэдэг тул A зөв. «成立» байгууллага байгуулахад, «构成» бүрдүүлэхэд, «实现» зорилго хэрэгжүүлэхэд хэрэглэгддэг тул мөнгөн тэмдэгтэд таарахгүй.'),
  ('e2a7e422-2145-4cf0-81f5-3e0719e32964'::uuid, 'Цоорхойн ард «的角逐» (өрсөлдөөн) гэсэн нэр үг байгаа тул түүнийг тодорхойлох тэмдэг нэр хэрэгтэй. «激烈的角逐» (ширүүн өрсөлдөөн) нь байнгын хэллэг тул B зөв. «深刻» ихэвчлэн сэтгэгдэл, ойлголтод, «强烈» хүчтэй мэдрэмж хүслийн үед, «彻底» бүрэн дүүрэн гэсэн утгатай тул «角逐»-той таарахгүй.'),
  ('a2f6c851-27d4-4d91-8a94-c0b0c211e86c'::uuid, 'Дараагийн өгүүлбэрт «他会很自然地为之鼓掌» (тэр өөр хүнд алга ташдаг) гэж байгаа тул цоорхойд «өрсөлдөгчийн төлөө алга ташсан нөхцөл байдал» орох ёстой. C «当竞争对手说到精彩处» (өрсөлдөгч сонирхолтой зүйл ярихад) л энэ утгад тохирно. Бусад сонголтууд өөрийнхөө амжилтын тухай өгүүлж байгаа тул холбогдохгүй.'),
  ('94a3b28e-dd80-49ca-950d-fca8481a2bea'::uuid, 'Цоорхойн ард «决定» (шийдвэр) гэсэн үг байгаа тул шийдвэрийн хэлбэрийг заасан дайвар үг хэрэгтэй. «一致决定» (санал нэгтэй шийдвэрлэх) нь байнгын хэллэг тул B зөв. «唯一» цорын ганц, «特意» санаатайгаар, «照常» ердийнхөөрөө гэсэн утгатай тул тохирохгүй.'),
  ('b4ce75ec-a5f2-4c89-8ab5-8af7cb6b982c'::uuid, 'Цоорхойн ард «别人的喝彩与祝福» (бусдын алга ташилт, ерөөл) гэсэн эд зүйл байгаа тул «авах, олж авах» гэсэн утгатай үг хэрэгтэй. «获得» (олж авах) тул A зөв. «达到» ихэвчлэн түвшин, зорилгод хүрэхэд, «积累» хуримтлуулахад, «保持» хадгалж үлдэхэд хэрэглэгддэг тул энэ агуулгад тохирохгүй.'),
  ('15a51da3-290c-42dc-b819-daee30b16b0d'::uuid, 'Цоорхойн ард «也大不相同» (бас маш их ялгаатай) гэж байгаа бөгөөд өмнөх өгүүлбэрт байшингийн загвар, барилгын хэв маягийн тухай өгүүлж байгаа тул «结构» (бүтэц) хамгийн тохиромжтой тул A зөв. «成分» найрлага, «比例» харьцаа, «规模» цар хэмжээ гэсэн утгатай тул байшингийн хэв маягт тохирохгүй.'),
  ('bd44b3e7-bee6-4e20-8110-06c86357d7b7'::uuid, 'Цоорхойн ард «白天时间较短，阳光也较少» (өдрийн цаг богино, нар бага) гэсэн шалтгаан ирж байгаа тул умард нутгийн өвлийг тодорхойлох «寒冷» (хүйтэн) хамгийн тохиромжтой тул B зөв. «光滑» гөлгөр, «清淡» амт багатай, «模糊» бүдэг зэрэг нь улирал тодорхойлоход хэрэглэгддэггүй.'),
  ('f8b901d7-3bcc-413f-aaec-22bbf47fc8b6'::uuid, 'Умард нутгийн байшин «向阳» (нар харсан тал руу) баригддаг шалтгаан нь өвлийн хүйтнээс хамгаалахын тулд байдаг тул D «有利于室内保温保暖» (өрөөний дулааныг хадгалахад ашигтай) хамгийн логиктой тул зөв. Бусад сонголтууд (байгаль хамгаалах, өртөг бууруулах гэх мэт) энэ шалтгаантай холбогдохгүй.'),
  ('e60098bc-058b-4c71-a92b-d47e74e5ab1a'::uuid, 'Хавтгай дээвэр нь материал хэмнэдэг тул «节省建筑材料» (барилгын материал хэмнэх) нь байнгын хэллэг тул C зөв. «控制» хянах, «克服» даван туулах, «争取» хичээн ажиллаж олж авах гэсэн утгатай тул «барилгын материал»-тай зохимжгүй.'),
  ('4d6d197d-b848-43f9-ba2b-7405121a2cef'::uuid, 'Цоорхойн ард «在第一位» (эхний байранд) гэж байгаа тул «байрлуулах, тавих» гэсэн үйл үг хэрэгтэй. «摆在第一位» (эхний байранд тавих) нь байнгын хэллэг тул B зөв. «提» ихэвчлэн асуулт тавих, дурдахад, «举» өргөхөд, «插» шигтгэхэд хэрэглэгддэг тул тохирохгүй.'),
  ('f805ba51-e20e-4322-a2ae-0a24a866f22d'::uuid, 'Дараа нь «所以强壮的身体是美好生活的基石» (тиймээс бяр чадалтай бие бол сайхан амьдралын үндэс) гэсэн дүгнэлт ирж байгаа тул өмнөх өгүүлбэрт бие сул байвал бүх зорилго хэрэгжихгүй гэсэн санаа хэрэгтэй. C «一切美好的愿望都是空想» (бүх сайхан хүсэл мөрөөдөл хоосон болно) нь энэ логикт тохирох тул зөв.'),
  ('4ea0bf4f-856f-4c28-bbdd-fa2b46d94c51'::uuid, 'Өмнөх өгүүлбэрт зөвхөн бие бяртай, хөдөлмөрч байхад л сайхан амьдарч болно гэвэл ухаан цэцэн байх шаардлагагүй болно гэсэн санаа байгаа тул «多余» (илүүц, шаардлагагүй) хамгийн тохиромжтой тул A зөв. «诚实» шударга, «均匀» жигд, «超级» супер гэсэн утгатай тул энэ агуулгад холбогдохгүй.'),
  ('6cd0849c-647d-4ce3-991b-4724df51f524'::uuid, 'Цоорхойн өмнө «才能让你懂得如何去___美好的生活啊» (сайхан амьдралыг хэрхэн яаж ... вэ гэдгийг л ойлгуулна) гэж байгаа тул «сайхан амьдрал»-тай хослох тохирох үйл үг хэрэгтэй. 享受 (эдэлж баясах) нь 享受美好的生活 (сайхан амьдралыг эдэлж баясах) гэсэн байнгын хослол үүсгэдэг тул зөв. 掌握 (эзэмших) мэдлэг ур чадварт, 承受/承担 (тэсвэрлэх, хариуцах) нь ачаа дааллагад хэрэглэгддэг тул энд тохирохгүй.'),
  ('fc8225a0-c013-402d-95ce-fc5e5ffb57eb'::uuid, '«疑人不用，用人不疑» гэдэг нь хүн ажилд авахын өмнө сайтар шалгаж, авсны дараа бүрэн итгэх ёстой гэсэн санаа. Эх бичвэрт «领导者在用人之前，必须十分谨慎» (удирдагч хүн авахаасаа өмнө маш болгоомжтой байх ёстой) гэж шууд бичсэн тул A «选人要谨慎» зөв.'),
  ('a33b78dc-b1ba-4de1-a4bf-5ad6c9d7be17'::uuid, 'Эх бичвэрт «财商不高的人容易乱投资、无节制地消费，最后不仅理不好财» (санхүүгийн ухаан багатай хүн санамсаргүй хөрөнгө оруулж, хэтрүүлэн зарцуулж эцэст нь мөнгөө зөв удирдаж чаддаггүй) гэж байгаа тул B «财商低的人不善理财» (санхүүгийн ухаан багатай хүн мөнгө удирдахдаа сайн биш) зөв.'),
  ('12477586-5cd7-4681-8697-db8bdc46fcb2'::uuid, '«被誉为“中华第一街”» (Хятадын нэгдүгээр гудамж хэмээн алдаршсан) гэдэг нь Ван Фүжин гудамж Хятадад маш алдартай болохыг харуулж байгаа тул B зөв. Худаг одоо байгаа эсэхийг эх бичвэрт дурдаагүй («从前» буюу урьд нь байсан гэж бичсэн), байршлын мэдээлэл ч бусад сонголттой зөрчилдөнө.'),
  ('1c48eefe-4e48-43ca-b5b5-275229affdb5'::uuid, '«对于不太熟悉的人，人们往往会根据对方的反应和外界条件来选择相应的言语或行为» (танихгүй хүмүүстэй бол хүмүүс нөгөө талын хариу үйлдэл, гадаад нөхцөлөөс хамааруулж үг яриа, зан төлөвөө сонгодог) гэсэн санаа тул C «言语行为多受环境影响» зөв.'),
  ('05207ccb-c0cb-416b-9ecb-9575a0d9f0ff'::uuid, '«可再生能源对环境无害或危害极小» (сэргээгдэх эрчим хүч байгаль орчинд хор хөнөөл бараг байхгүй) гэдэг нь D «可再生能源不易污染环境»-тэй тохирно. Эх бичвэрт «取之不尽、分布广泛» гэж эсрэгээрээ бичсэн тул A, B, C буруу.'),
  ('6f480b9c-647b-4de5-99f2-0eb7e1928f1b'::uuid, '«湖广熟，天下足» гэдэг нь Хунань, Хубэй мужууд будаа арвин ургуулбал бүх улс цатгалан болдог гэсэн үг бөгөөд «明清时期...湖广地区作为全国最重要粮食产地的地位得以巩固» гэж бичсэн тул B «明清时湖广粮食产量很高» зөв.'),
  ('3d051787-e3c6-4028-bb48-66d50d622aec'::uuid, 'Эцэг завиа усаар дүүргэснээр тогтворжсон жишээгээр «负重的生命也许更有韧性、更有意义» (ачаа даасан амьдрал илүү тэсвэртэй, илүү утга учиртай байж болно) гэсэн санааг илэрхийлж байгаа тул C зөв.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('185b835e-4ec2-435e-8eb8-97848c568e84'::uuid, '«自此，羊肉泡馍成了风靡长安的美食» (үүнээс хойш ямааны махтай будаа Чан Ань хотод их түгээмэл хоол болсон) гэж шууд бичсэн тул D «羊肉泡馍在长安很流行» зөв.'),
  ('45f86f77-cf13-46e0-9a78-3e5e3035b80e'::uuid, 'Эх бичвэрт «至少我们应该做到平静，平静地看待这件事» (дор хаяж бид тайван байж, тайван байдлаар харах ёстой) гэсэн санаа давамгайлж байгаа тул A «要平静地对待失败» зөв.'),
  ('cede8ab9-0b81-46a1-b617-37e51c7f1a90'::uuid, '«难得糊涂»-ийн утга нь «贵在理解» (ойлголцох нь чухал) гэж тайлбарлаж, «应给予彼此更多的理解和包容» гэж бичсэн тул A «相处之道重在理解» зөв.'),
  ('e53d57df-6c68-4489-8df4-3e75abd6fa36'::uuid, 'Эх бичвэрт «牛奶糖比较软，而椰子壳比较硬» (сүүн чихэр зөөлөн,椰子 хясаа хатуу) гэж шууд тайлбарласан тул B зөв. Туршилтын нөхцөл, арга, шидэлтийн талаар гомдол дурдаагүй тул бусад сонголт таарахгүй.'),
  ('57362152-c4da-4940-82e9-58f41e1fed5e'::uuid, '«我们往往受限于日常的生活经验，认为有些事情是不可能发生的» (бид ихэвчлэн өдөр тутмын туршлагадаа хязгаарлагдаж зарим зүйл боломжгүй гэж боддог) гэсэн санаа тул C «不要受经验的限制» зөв.'),
  ('e8e88a63-acb9-4601-a7b6-4fd139e31b9c'::uuid, '«妄自菲薄» гэдэг нь эх бичвэр доторх «以为自己没什么才能» (өөрийгөө чадваргүй гэж боддог) гэсэн санаатай ойролцоо, өөрөөр хэлбэл өөрийгөө хэтрүүлэн дорд үзэх гэсэн утгатай. Тиймээс B «过分看轻自己» зөв.'),
  ('aca62c7d-2575-4c61-953c-2443ca998516'::uuid, 'Эх бичвэрийн санаа нь зөөлөн зүйл (牛奶糖) ч зөв хэлбэр, байрлалтай бол асар их хүчийг гаргаж чадна гэдэг тухай өгүүлж байгаа тул A «柔软的力量» гарчиг болгоход хамгийн тохиромжтой.'),
  ('ee72aa23-3809-40f2-9d76-918df941d24e'::uuid, 'Хүү «三»-ыг сурсныхаа дараа «认字很简单，我已经学会了» (үсэг таних амархан, би сурчихлаа) гэж хэлж, багшийг халаасан тул C «儿子觉得写字简单» зөв.'),
  ('7ba2e3bd-3f2f-4af1-9831-45cd235223c4'::uuid, '«眼看太阳都下山了，还不见儿子写好» гээд эцэг нь хүүгийнхээ өрөөнд орж хараад «拿着笔在纸上一道儿一道儿地画着» гэж байна — хүү урилгын захидлаа бичиж дуусгаагүй байсан. Тиймээс D «儿子一直没把请帖给他» зөв.'),
  ('c54d36ab-98a8-47f2-88b0-eec512362bc2'::uuid, 'Эх бичвэрийн төгсгөлд «如果我们学习也只满足于一知半解，那和地主的笨儿子又有什么区别呢» (хагас дутуу мэдлэгээр сэтгэл ханывал тэнэг хүүтэй ялгаагүй) гэж бичсэн нь хүү үнэндээ бичиж сурсангүй гэдгийг харуулж байгаа тул D «没有真正学会写字» зөв.'),
  ('aaeab34e-ca69-48ef-b01c-6c17e2cd7666'::uuid, 'Түүх нь тэнэг хүү бичиг үсгийг буруу ойлгосон тухай өгүүлж байгаа тул гарчиг C «笨儿子学写字» хамгийн тохиромжтой.'),
  ('6fd929c3-ace3-4945-8b46-397d9a64c323'::uuid, 'Будааны жишээгээр «是什么使那锅米饭变坏的呢？是时间» (юу нь будааг муутгасан бэ? Цаг хугацаа) гэж эхэлж, цаг хугацааны нөлөөг тайлбарладаг тул A «时间的作用» зөв.'),
  ('d261d091-7fdd-4a69-b808-217fe76a4707'::uuid, '«女儿红» бол охин төрсний дараа хадгалж, хуримын үеэр гаргадаг «佳酿» (сайхан амттай дарс) гэж тодорхойлсон тул A «是一种美酒» зөв.'),
  ('561b3f9c-6eda-4928-a010-970b9d948bc7'::uuid, '«关键就在于内心深处是否有对真善美的渴望...这就要看我们是以什么态度来要求自己了» гэж хүний хандлага хамгийн чухал болохыг онцолсон тул A «人生态度» зөв.'),
  ('700cc7d9-568d-445d-bba1-014ecb0f4381'::uuid, '«关键就在于内心深处是否有对真善美的渴望» (гол нь дотоод сэтгэлдээ үнэн-сайн-гоо сайхныг хүсэх эсэхэд байдаг) гэдэг нь өндөр ёс суртахуунтай хүн үнэн, сайн сайхныг эрэлхийлдэг гэсэн санааг илэрхийлж байгаа тул C «品德高尚的人追求真善美» зөв.'),
  ('27143632-acaf-4c42-81a7-e1336de282c6'::uuid, 'Гэрэл зурагчин «作品经常被刊登在国际知名的报刊杂志上...举办过十几次个人影展...屡次获得国际大奖» гэж амжилттай хүн болохыг тайлбарласан тул B «事业很成功» зөв. «学习成绩一落千丈» (сургуулийн дүн буурсан) гэж бичсэн тул C буруу.'),
  ('cc0d8d2f-0b71-4e6a-ad02-c1810d2a628f'::uuid, '«必须样样第一才行，但这当然是不可能的。于是，他心灰意冷» гэдэг нь хүсэл нь биелэхгүй болоод урам хугарч гуниглах утгыг илэрхийлж байгаа тул A «失望难过» зөв.'),
  ('b7b9517e-2751-4932-bb6b-7291c46b1bbc'::uuid, '«玉米粒相互挤着，竟一粒也没有掉下来» гэж шууд бичсэн тул D «没有一粒玉米掉下来» зөв.'),
  ('e4b65048-d40b-4ba0-8340-48c33a453291'::uuid, 'Эцгийн үгэнд «假如你每天都能做好一件事，那你每天都会有一粒种子的收获...当你把所有的事情都挤到一块儿来做，那你连一粒种子也收获不到» гэж байгаа тул нэг дор олон зүйл хийхээс илүү анхаарлаа нэг зүйлд төвлөрүүлэх нь дээр гэдгийг заасан. Тиймээс D «应先集中精力做好一件事» зөв.'),
  ('12ae4494-b37d-43c5-a342-e62d2e7ab9b5'::uuid, '«他曾在墙壁上画过两只鹰，吓得一些小鸟从此不敢在屋檐下做窝» гэдгээс шувуунууд зурсан бүргэдийг жинхэнэ бүргэд гэж андуурсан гэдэг нь ойлгогдож байна. Тиймээс D «以为见到了真的鹰» зөв.'),
  ('6013063e-8efa-4269-8514-27c8584e0f9b'::uuid, '«画上眼睛的两条龙破壁飞去...墙壁上只剩下两条没画上眼睛的龙» гэж шууд бичсэн тул C «画上眼睛的龙飞走了» зөв.'),
  ('e1b34d87-130a-4ec8-b787-248f6936bacd'::uuid, '«他笔下的飞禽走兽栩栩如生» (зурсан амьтад нь амьд мэт харагддаг) гэдэг нь зураачийн ур чадвар маш өндөр гэдгийг харуулж байгаа тул B «绘画技术很高» зөв.'),
  ('6cbb733c-acc2-47be-bc1f-bf97dc8bdad5'::uuid, 'Бүх өгүүллэг нь «画龙点睛» хэмээх зүйр үгийн гарал үүслийг өгүүлж байгаа тул D «成语“画龙点睛”的由来» зөв.'),
  ('8023ea88-e90f-4189-8929-68602e8bd68d'::uuid, 'Зөв бүтэц: «请您主动出示证件。» «请» хүсэлтийн үгийн ард хэнд хандаж буйг заасан «您» ордог, дараа нь дайвар үг «主动» (идэвхтэй) үйл үгийн өмнө, эцэст нь «出示证件» (бичиг баримтаа харуулах) тогтмол хэллэг ирнэ.'),
  ('7843d731-bbfd-4852-9f95-1a674542f33f'::uuid, 'Зөв бүтэц: «这条牛仔裤一点儿都不结实。» «一点儿都不» гэдэг нь «огт... үгүй» гэсэн онцлон үгүйсгэх хэллэг бөгөөд тэмдэг нэр «结实» (бат бэх)-ийн өмнө байрладаг.'),
  ('165318ad-852c-4143-a41c-2dc69a25fa51'::uuid, 'Зөв бүтэц: «开幕式将于本月中旬举行。» «将于+цаг хугацаа+举行» нь «тухайн үед болно» гэсэн албан ёсны хэллэг тул цаг хугацааны нэр үг «本月中旬» дунд, гол үйл үг «举行» төгсгөлд ирнэ.'),
  ('1b2aa91c-909d-4d96-ae9d-7c11a026ad5f'::uuid, 'Зөв бүтэц: «这家企业在建筑行业很有名。» «在建筑行业» нь аль салбарт гэдгийг заасан байрлалын хэллэг бөгөөд өгүүлэгдэхүүн «这家企业»-ийн дараа, тодорхойлолт «很有名»-ийн өмнө орно.'),
  ('0b3e7f1e-4916-46ed-83c8-d361149c49f6'::uuid, 'Зөв бүтэц: «他的情绪已经稳定下来了。» «稳定下来» (тогтворжих) нь үр дүнгийн нэмэлттэй үйл үг хэллэг, «已经...了» нь үйл явдал аль хэдийн болсныг заана.'),
  ('053c998c-357e-4b37-91e0-975449c1e9f0'::uuid, 'Зөв бүтэц: «名片上有我的联系方式。» «名片上» (нэрийн хуудсан дээр) + «有» (байх) + «我的联系方式» (миний холбоо барих хаяг) — байршил зааж буй «有»-өгүүлбэрийн бүтэц.'),
  ('c2f1a49e-b69d-4011-b9bf-c17171c2b9d8'::uuid, 'Зөв бүтэц: «他提的方案值得我们参考。» «他提的方案» (тэр гаргасан төлөвлөгөө) өгүүлэгдэхүүн болж, «值得+хийх үйлдэл» (值得我们参考) нь «...хийх нь зохимжтой/үнэ цэнэтэй» гэсэн бүтэц.'),
  ('fb235fc5-aa31-4084-9ea1-c73da36fafbd'::uuid, 'Зөв бүтэц: «志愿者们受到了热烈的欢迎。» «志愿者们» өгүүлэгдэхүүн, «受到了热烈的欢迎» (халуун дотно хүлээн авалтад хүртсэн) нь идэвхгүй утгатай «受到» бүтцээр илэрхийлэгдэнэ.'),
  ('3b01247c-cfe8-42af-bfb2-96df6edd410b'::uuid, 'B сонголт дахь «有没有坚定的信念» (итгэл үнэмшилтэй эсэх) гэсэн ХОЁР ТАЛТ хэлбэр нь ард нь ирэх «是成功的先决条件» (амжилтын урьдчилсан нөхцөл) гэсэн НЭГ ТАЛТ (эерэг) дүгнэлттэй зохицохгүй байна. Зөв бол зөвхөн «有坚定的信念» гэж эерэгээр бичих ёстой. A, C, D өгүүлбэрүүд дүрмийн хувьд зөв.'),
  ('6e7b3110-73c6-4092-b020-3f055c6702dc'::uuid, 'C сонголтод «经过显微镜» гэдэг буруу — «经过» нь цаг хугацаа, газар дайрч өнгөрөхийг илэрхийлдэг үг тул энд тохирохгүй. Харин арга хэрэгслийг илэрхийлэхэд «通过显微镜» (дуран ашиглан) гэж хэрэглэх ёстой. A, B, D өгүүлбэрүүд зөв бүтэцтэй.'),
  ('83dac44a-dc0d-4b6b-88a8-301db1bc1b64'::uuid, 'C өгүүлбэрт «翻天覆地发生了变化» гэдэг үгийн дараалал буруу — «翻天覆地» (асар их) гэсэн тэмдэг нэр нь «变化» (өөрчлөлт)-ийг тодотгох ёстой тул «发生了翻天覆地的变化» гэж байрлах ёстой. A, B, D өгүүлбэрүүд дүрмийн алдаагүй.'),
  ('2a6608d2-4c45-49b9-a5be-6da6393dfeca'::uuid, 'B сонголтод «焰火...组织了一幅...图案» гэдэг үг буруу хэрэглэгдсэн — «组织» нь хүмүүс, үйл ажиллагааг зохион байгуулахад хэрэглэдэг үг тул зураг дүрс үүсгэхэд тохирохгүй. Оронд нь «组成» эсвэл «构成» (бүрдүүлэх) гэж байх ёстой. A, C, D өгүүлбэрүүд зөв.'),
  ('010bfdbe-7224-45f4-a757-191a6328ff5f'::uuid, 'D өгүүлбэрт «无一不是吸引游客来的» гэсэн хэсэг найруулгын хувьд гишүүн дутуу — «...来的»-ийн ард юуг илэрхийлж байгаа нь тодорхойгүй, өгүүлбэрийн гишүүн бүрэн бус байна. A, B, C өгүүлбэрүүд бүтэц зөв, ойлгомжтой.'),
  ('7e456fa3-d23e-4a98-8bfd-ab2d795ccf25'::uuid, 'C өгүүлбэрт «雨花石天然细腻的花纹，玲珑剔透的质感，被誉为...» гэдэгт өгүүлэгдэхүүнүүдийг холбох «以» (-аар) гэсэн угтвар дутуу — «雨花石以...花纹、...质感，被誉为» гэж засах ёстой. A, B, D өгүүлбэрүүд бүрэн зөв.'),
  ('7f424b76-d65d-4248-8c10-2bdca88cd824'::uuid, 'D өгүүлбэрт «做了详细报道对这起...事件» гэдэг үгийн дараалал буруу — «对+юу» гэсэн угтвар хэллэг үйл үгийн ӨМНӨ орох ёстой тул «对这起...事件做了详细报道» гэж засах ёстой. A, B, C өгүүлбэрүүд дүрмийн хувьд зөв.'),
  ('7ebfce47-1683-44ac-86b7-301b185aabb3'::uuid, 'C өгүүлбэрт «还有可能引发各种疾病的可能性» гэдэг утга давхардсан — «可能» ба «...的可能性» хоёр ижил утгыг давхар илэрхийлж байна. «还可能引发各种疾病» гэж хялбарчлах ёстой. A, B, D өгүүлбэрүүд зөв.'),
  ('8edd4e22-1fb7-436c-b4e5-c05f80e3f681'::uuid, 'D өгүүлбэрт «从而逐渐融入音乐和舞蹈» гэдэгт «从而» (үүний үр дүнд) гэсэн шалтгаант холбоос буруу хэрэглэгдсэн — энд шууд шалтгаан-үр дагаврын холбоо биш, зүгээр цаг хугацааны дараалал тул «后来»/«逐渐» гэх мэт үг хэрэглэх ёстой. A, B, C өгүүлбэрүүд зөв.'),
  ('1103499c-14a7-46fb-85c4-b3e9b0fcd33c'::uuid, 'D өгүүлбэрт «之所以提倡...的原因是因为» гэдэг хэллэг найруулгын хувьд давхардсан — «之所以...是因为» болон «...的原因是...» гэсэн ХОЁР өөр бүтцийг зэрэг хэрэглэсэн байна. Зөвхөн нэгийг нь сонгож бичих ёстой. A, B, C өгүүлбэрүүд зөв.'),
  ('e54198ae-3526-4023-8d5c-10a1619452a2'::uuid, '«陈述的顺序___» гэдэгт «至关重要» (маш чухал) тохирно, учир нь дараалал буруу бол сэтгэгдэл эрс өөрчлөгддөг гэж дурдсан байна. «即使» (хэдийгээр ч гэсэн) холбоос нь зөрчилтэй нөхцлийг сайн холбоно, харин «180度的___» гэдэгт «转变» (өөрчлөлт) хамгийн зохимжтой — «转移», «转让», «转折» нь энд утга нийцэхгүй.'),
  ('17b2e883-8840-492b-876e-87cf85e2042b'::uuid, 'Мөс наранд «融化» (хайлах) тул эхний хоосон зай тохирно. «沙漠是冰的地狱，北极才是冰的___» гэдэгт «地狱» (там)-тай эсрэг утгатай «天堂» (диваажин) тохирно. Мөн «冰在沙漠才最___» гэдэгт цөлд ховордсон учир «珍贵» (үнэтэй, ховор) тохирно. «消弱/溶解/照耀» зэрэг нь энд утга дутуу.'),
  ('df642380-adc9-4cc8-90ca-b6ef9b96fd57'::uuid, '«在___的大风中» гэдэгт салхины хүчийг илэрхийлэх «猛烈» (хүчтэй, ширүүн) тохирно. «坚定的___» гэдэгт «立场» (байр суурь) хамт хэрэглэгддэг тогтмол хэллэг. Эцэст нь «经得起___» (тэсвэрлэх) гэдэгт «考验» (сорилт) л зохицдог тогтмол холбоо үг — «梦想/观念/考察» нь тохирохгүй.'),
  ('44293949-f815-49d5-85dc-19a3ae0c3b89'::uuid, '«周期性喷发» (тогтмол мөчлөгтэй дэлбэрэлт) гэдэг нь идэвхтэй галт уулын тодорхойлолт. «之后未喷发过» гэдэгт «未» (хараахан...гүй) тохирно. «人类有史以来» бол тогтмол хэллэг. Эцэст нь «长期处于平静状态» гэдэгт «平静» (тайван) тохирно.'),
  ('b606a75a-470a-4354-b032-d8f2c0a90a6e'::uuid, '«不自觉地撒谎» (санамсаргүйгээр худал хэлэх) гэдэгт «自觉» тохирно. «坏___» гэдэгт «行为» (үйлдэл) хэрэглэгддэг. «人际关系更___» гэдэгт «融洽» (эв найртай) тохирно. Эцэст нь «___的一种技巧» гэдэгт хүмүүстэй харилцах ур чадварыг илэрхийлэх «待人接物» тохирно.'),
  ('4d9b069a-e115-4fe0-8970-59d9681bf282'::uuid, 'Гудамжны байдлыг тодорхойлохдоо «纵横» (замууд холилдсон) тохирно. «倘若» (хэрэв) нь нөхцөлийн холбоос. «难以分辨东南西北» гэдэгт «分辨» (ялгах) тохирно. Эцэст нь «犹如进了迷宫一般» (лабиринтэд орсон мэт) гэдэгт «犹如» (адилхан) тохирно.'),
  ('bda372b1-3f25-416e-a7b6-d84953c0cc01'::uuid, '«不正确的___习惯» гэдэгт «饮食» (хооллолт) тохирно. «最___的减肥方法» гэдэгт зардалгүй тул «实惠» (хэмнэлттэй) тохирно. «有___的睡眠» гэдэгт «规律» (тогтмол) тохирно. Эцэст нь «节省不必要的___» гэдэгт «开支» (зарлага) л тогтмол хамт хэрэглэгддэг.'),
  ('f25cc38b-11ec-40b9-81d2-74f0b52caab2'::uuid, '«这___于他早年的苦读强记» гэдэгт «得益» (ач тусаас үүдэлтэй) тохирно. Үг алдаагүй ярих чадварыг «一字不差» (үг бүр таарсан) гэж тэмдэглэсэн нь тохиромжтой. «吐字___» гэдэгт «清晰» (тод) тохирно. Үзэгчид «拍手叫绝» (алга ташин магтах) гэдэг нь зөв илэрхийлэл.'),
  ('55e358dc-3419-4676-a707-1c40c2a6db52'::uuid, 'Номын агуулгыг «透彻» (гүнзгий, тодорхой) ойлгосон гэдэг тохирно. Номын гол санааг «要点» (гол цэг) гэж нэрлэдэг. Бүлэг тус бүрийг «深入探讨» (гүнзгийрүүлж хэлэлцэх) хийх нь зохимжтой. Эцэст нь материалаа баяжуулах утгад «补充» (нэмэлт хийх) тохирно.'),
  ('32677733-cd7f-4bc0-ba7d-6f65dbbf9338'::uuid, 'Энэ асуултын өгөгдсөн сонголтуудын бичвэр эх өгүүлбэртэй (1960 оны усан бэхийн хөдөлгөөнт кино тухай) нийцэхгүй байна — A-D сонголтууд нь өөр асуултын (76-80-р асуултын лууван түүхийн) хариултуудтай ижил бөгөөд файлд өгөгдлийн алдаа орсон бололтой. Иймд зөв хариулт D-г эх бичвэрээс баталж чадахгүй тул эх материалтай тулгаж үзэхийг зөвлөж байна.'),
  ('f3b9cf6c-7dd5-4e1b-a979-8ed066e2bc14'::uuid, '71-р зайны дараа «使鱼在静止状态时，能够自由控制身体处在某一水层» (загас хөдөлгөөнгүй үедээ биеэ тодорхой усны давхаргад байлгаж чадна) гэж үр дүнг заасан тул шалтгаан болох A «鱼鳔产生的浮力» (загасны хүүдийн үүсгэсэн хөвөлт) тохирно. Бусад сонголтууд энд логикоор оромгүй.'),
  ('73b439d5-5a02-453b-bc1f-373bbb0caeea'::uuid, '72-р зай нь өмнөх хоёр өгүүлбэрт дурдсан хүүдийн ач холбогдлыг (биеэ хянах, дотоод эрхтнийг хамгаалах) нэгтгэн дүгнэх байрлалд байгаа тул C «鱼鳔掌握着鱼的生死存亡» (хүүд загасны амь наслалтыг захирна) хамгийн тохиромжтой ерөнхий дүгнэлт болно.'),
  ('ac4511ff-84f1-4239-9462-59631f45abf6'::uuid, '«有一种鱼却是异类，（73）。而且...它就是被誉为«海洋霸主»的鲨鱼» гэдгээс харахад дараа нь ялгарах загас (акул) тухай өгүүлж эхэлж байгаа тул E «它天生就没有鳔» (энэ загас төрөлхөөсөө хүүдгүй) тухайн ялгарах шинжийг танилцуулна.'),
  ('0f214498-41a0-4c4e-93bd-b46513c69d3e'::uuid, '«鲨鱼由于没长鳔，一旦停下来，身子就会下沉,（74），永不停息地在水中游弋» гэдгээс харахад живэхээс сэргийлэхийн тулд акул юугаар хөдөлдгийг тайлбарлах ёстой тул D «所以它只能依靠肌肉的运动» (тиймээс зөвхөн булчингийн хөдөлгөөнд найдна) логикоор яг тохирно.'),
  ('b3b55e48-b52f-4c1d-a34b-892248831aca'::uuid, '«...练就了非凡的战斗力。（75）。鲨鱼无鳔，这是它的悲，也是它的喜» гэдэг өгүүлбэрийн өмнө байрлах тул хүүдгүй байдал нь сул тал боловч хүчирхэг болгосон тухай дүгнэлт хэрэгтэй — B «原来正是鲨鱼天生的缺陷造就了它的强大» (яг л акулын төрөлхийн дутагдал нь түүнийг хүчирхэг болгосон юм байна) энэ санааг илэрхийлнэ.'),
  ('fc5ff973-6f31-44f4-8724-c14aced9c7d6'::uuid, '«刘墉一听，喜形于色，（76）» гэдэгт баяртай сэтгэлээ илэрхийлж байгаа тул E «兴致勃勃地比划着自己家乡远近闻名的大萝卜» (сэтгэл догдлон нутгийнхаа алдартай том лууван тухай гараар зааж тайлбарлав) тохирно.'),
  ('b625b85e-0b22-4169-9682-5646e0357644'::uuid, '«刘墉听后很不服气...（77）。乾隆皇帝听了觉得很好笑» гэдгээс хоёулаа үргэлжлүүлэн маргалдсаныг илэрхийлэх ёстой тул C «两人为此争论不休» (хоёул үүнээс болж үргэлжлүүлэн маргав) тохирно.'),
  ('365a4f50-150c-4579-84f6-2fd5c9f75bb4'::uuid, '«刘墉带着一个大萝卜上朝，大臣们看到那么大的萝卜，（78）» гэдэгт сайдууд том луувангийн талаар ямар хариу үзүүлснийг заах ёстой тул D «个个赞叹不已» (хүн бүр гайхан магтав) тохирно.'),
  ('79e46125-e62c-4446-a74f-3da414e51b0c'::uuid, '«纪晓岚从袖口内掏出一个又瘦又小的萝卜。大臣们看了不禁议论纷纷，（79）» гэдэгт жижиг лууван гаргаж ирснийг хараад сайдууд юу бодож байгааг заах ёстой тул A «不知他葫芦里卖的是什么药» (түүний санаа юу болохыг мэдэхгүй байна гэсэн хэлц үг) тохирно.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('6a26a5fd-e70e-4c93-bf9b-dd620f54ea5e'::uuid, '«乾隆这才明白，（80）。于是...说：直隶穷就少纳粮，山东富就多纳些粮吧！» гэдгээс харахад хааны ойлгосон зүйл нь татварын шийдвэртэй холбоотой байх ёстой тул B «纪晓岚是在借机反映直隶省经济困难» (Жи Сяолань энэ тохиолдлыг далимдуулан Жили мужийн эдийн засгийн хүндрэлийг мэдэгдэж байсан юм байна) тохирно.'),
  ('2eec2932-344b-4f7e-afa4-ff1e4c3b13dd'::uuid, '«正中商家下怀» гэдэг хэлц үг нь худалдаачны хүссэн, тооцоолсон зүйл яг тохирч гарсныг илэрхийлдэг тул B «符合商家的意愿» (худалдаачны хүсэлд нийцэх) тохирно. Энд «下怀» нь «сэтгэлийн эрхэм хүсэл» гэсэн утгатай тул C, D (сэтгэл дундуур байх, эсрэгээрээ) буруу.'),
  ('2590e840-e38c-49c8-817a-1334aa4e59f6'::uuid, 'Эх бичвэрт «自从采取捆绑式销售后，这两件商品就变得热销起来» (боож зарсны дараа хоёр бараа ихээр борлогдож эхэлсэн) гэж дурдсан тул шинэ маркетингийн стратеги «成效显著» (үр дүн мэдэгдэхүйц) байсныг харуулна — A зөв.'),
  ('80cd240b-a88f-49fe-933e-f0c51416d5d8'::uuid, 'Эх бичвэрийн төгсгөлд «更应研究消费者的心理，了解和把握消费者的心态» (хэрэглэгчийн сэтгэл зүйг судалж, ойлгож байх хэрэгтэй) гэж шууд дүгнэсэн тул C «要善于把握顾客心理» зөв хариулт.'),
  ('605d5b60-0b5d-4670-8857-8e749486775a'::uuid, 'Бүх эхэд «诱饵效应» (хууч-нэрийн нөлөө) гэсэн ойлголтыг тайлбарлаж, жишээгээр баталгаажуулсан тул үндсэн сэдэв нь C «营销中的«诱饵效应»» (маркетинг дахь «хууч» нөлөө) мөн.'),
  ('e1c3a184-a4d1-430e-bd7e-abe287d44565'::uuid, '崔永元-гийн хэлсэн «只有你的历史不再支离破碎» (түүх чинь эвдэрсэн хэсэг хэсэг байхаа больж байж) гэдэг үг нь аман түүх бичиж үлдээх нь түүхийг илүү бүрэн, тодорхой болгодог гэсэн санааг илэрхийлж байгаа тул A «能使历史更完整» зөв.'),
  ('2ad65f5f-adb3-4709-8470-e2584e1a0abc'::uuid, 'Эх бичвэрт崔永元-ий сая гаруй хүний аман түүх бүртгэсэн (B), Хятадын аман түүхийн эхлэлийг тавьсан (C), судалгааны төв байгуулахад оролцсон (D) гэж дурдсан ч тусгай нэвтрүүлэг нээсэн тухай огт дурдаагүй тул A «开设了口述历史栏目» дурдагдаагүй зүйл болно.'),
  ('55d2e6ec-baa7-4e32-a782-e32bfe748943'::uuid, 'Эх бичвэрт «崔永元打算在博物馆建好后，分两步对公众开放：第一步，对学者和从业者开放» гэж тодорхой заасан тул C «将率先对学者开放» зөв — «要什么资料，无偿提供» (үнэгүй) нь A-г, «最困难的是软件» нь B-г тус тус үгүйсгэнэ.'),
  ('41a92cd5-e850-4f26-9b76-971c38ffec21'::uuid, 'Эх бичвэр бүхэлдээ崔永元 хүний хүчин чармайлт, хийсэн ажил, төлөвлөгөөг өгүүлж байгаа тул D «崔永元对中国口述历史的贡献» (崔永元-ий Хятадын аман түүхэнд оруулсан хувь нэмэр) хамгийн тохиромжтой ерөнхий сэдэв.'),
  ('2c5296fe-82bb-40f8-9514-e43daa117a17'::uuid, '«如出一辙» гэдэг хэлц үг нь «яг адилхан, ялгаагүй» гэсэн утгатай тул утга ойролцоо үг нь B «相差无几» (бараг ялгаагүй) мөн. «南辕北辙» эсрэг чиглэлд явахыг, «形同陌路» танихгүй мэт харьцахыг илэрхийлдэг тул тохирохгүй.'),
  ('5bc1220f-6f42-48fd-b793-935b7ea1c2f4'::uuid, 'Эх бичвэрт «刚开始，幼猴一边尖叫，一边撞击笼子，情绪极不稳定» (эхэндээ бяцхан сармагчин хашгиран тор мөргөж, сэтгэл санаа тогтворгүй байсан) гэж дурдсан тул A «焦躁不安» (түгшүүр, тайван бус) зөв хариулт.'),
  ('be7466e4-6b2a-4120-b182-40dc75ff06ac'::uuid, 'Эх бичвэрт «如今，这个观点被广泛认同» (одоо энэ үзэл өргөнөөр хүлээн зөвшөөрөгдсөн) гэж дурдсан тул A «实验结论被广泛认可» зөв. «铁丝母猴能提供肢体接触» (D) буруу — учир нь зөвхөн даавуун эх л биеийн харьцаа өгдөг гэж дурдсан.'),
  ('24760cca-9d43-4df2-a81c-866360dd177e'::uuid, 'Эх бичвэрийн эцэст «心理学家由此得出结论：爱源自接触，而非食物» гэж шууд дүгнэсэн тул B «爱源自接触» (хайр нь хүрэлцэхээс үүсдэг) яг үнэн.'),
  ('e82a3dde-efcb-49e3-bf97-af4bd62989a8'::uuid, 'Эхний догол мөрөнд 郭守敬-ийн тухай «他先后主持修建了20多项农田灌溉、河道航运工程» (тэрээр 20 гаруй усалгаа, усан замын байгууламж барьсан) гэж дурдсан тул D «修建了多项水利工程» зөв. «精通数学» (A) нь үнэндээ түүний өвөө 郭荣-д хамаатай.'),
  ('80a7d456-f621-4a28-89d0-1aa5d0a98ef7'::uuid, 'Эх бичвэрт «在此之前已经有许多水利方面的专家试图开凿它，均因水源问题得不到解决而以失败告终» (усны эх үүсвэрийн асуудал шийдэгдэхгүй байсан тул амжилтгүй болсон) гэж тодорхой дурдсан тул C «水源难寻» зөв.'),
  ('d35bdff8-8882-4809-9fe4-3d4c850fdede'::uuid, 'Эх бичвэрт «根据大都周围西北高、东南低的地形，将...白浮泉先引入瓮山泊» (газрын гадаргын налууг ашиглан ус татсан) гэж дурдсан тул A «利用地势引水» зөв. «要在运河上游建立闸门» (D) буруу — учир нь хаалт хаалганууд «下游» (доод урсгал)-д баригдсан.'),
  ('62aeecc5-5b1a-4cf5-81b3-1573d677954f'::uuid, 'Тухайн эх бичвэр бүхэлдээ 郭守敬 хэрхэн 通惠河 (Тунхуэй суваг)-ийг ухаж байгуулсныг тодорхой өгүүлж байгаа тул B «通惠河的开凿» хамгийн зохимжтой гол сэдэв. A нь зөвхөн 忽必烈-тай холбоотой тул хэт нарийсгасан. (Анхаар: C, D сонголтын бичвэр өгөгдөлд гэмтэлтэй/өөр эхээс холилдсон байгаа тул тэдгээрийг тулгаж чадаагүй.)'),
  ('bfdbf2e6-a3ff-413c-8d31-c384e82a71c8'::uuid, 'Эх бичвэрт «硒» (селен), «镁» (магни), «番茄红素» (ликопен) гурав нь тус тус хорт хавдраас сэргийлэх үүрэгтэй гэж тодорхой дурдсан ч «叶酸» (фолийн хүчил)-ийг зөвхөн «心脏的保护神» (зүрхний хамгаалагч) гэж дурдсан тул хорт хавдраас сэргийлэх талаар дурдаагүй нь C болно.'),
  ('585b16a6-f5eb-43b3-b923-b4a8b827a38f'::uuid, 'Эх бичвэрт «玉米含有丰富的不饱和脂肪酸，尤其是亚油酸的含量在60%以上» гэж тодорхой дурдсан тул B «亚油酸含量很高» (линолийн хүчлийн агуулга өндөр) зөв. «营养价值不如大米» (C) буруу — учир нь эсрэгээрээ «玉米的营养价值最高» гэж дурдсан.'),
  ('e389623c-d84f-409e-a7cd-55af6fde56a8'::uuid, 'Эх бичвэрт «绿茶的保健功能是发酵类茶所不及的» (ногоон цайны эрүүл мэндэд үзүүлэх нөлөө исгэсэн цайнаас илүү) гэж тодорхой дурдсан тул D «绿茶具有较好的保健功能» зөв. «辣椒素对身体有害» (A) буруу — учир нь эсрэгээрээ даралт, холестерин бууруулдаг гэж дурдсан.'),
  ('18ef5a5c-db59-4272-8171-162de4558131'::uuid, 'Эх бичвэр улаан, шар, ногоон, хар өнгийн хүнсний тус бүрийн эрүүл мэндэд үзүүлэх ач тусыг жагсаасан тул гарчиг болгоход хамгийн тохиромжтой нь A «有色食品益处多» (өнгөт хүнс ач тус их) юм. B нь зөвхөн тодорхойлолт агуулах тул хэт нарийсгасан.'),
  ('37d70793-dcad-4814-a01f-9fc392a631df'::uuid, 'D сонголтод „防止人们在运动中不受伤“ (хүмүүсийг спортын үед бэртэхээс сэргийлнэ) гэдэгт „防止“ (сэргийлэх) ба „不“ (үгүй) хоёрыг зэрэг хэрэглэснээс утга нь эсрэгээрээ гарчээ — зөв нь „不“-г хасаж „防止...受伤“ гэх ёстой. Бусад A, B, C өгүүлбэрүүд дүрмийн хувьд зөв.'),
  ('18221293-d562-40f5-985c-962216defa5b'::uuid, 'B сонголтод „是食药兼用“ гэж төгссөн нь дутуу өгүүлбэр — „是“ (байх) үйл үгийн ард нэр үгийн хэллэг (жишээ нь „佳品“) байх ёстой атал үйл хэллэгээр төгссөн тул гишүүн дутуу алдаатай. Бусад сонголтууд бүтэц зөв.'),
  ('7ae54554-652d-47e4-aaf6-aee288b23afa'::uuid, 'C сонголтод „意志坚韧是否“ гэдэг нь үгийн дараалал буруу — „是否“ (эсэх) нь тэмдэг нэрийн өмнө орох тул зөв хэлбэр „是否坚韧“ байх ёстой байв. Бусад сонголтууд дүрмийн хувьд зөв.'),
  ('0d1a4985-c0ae-4a7a-a103-ac7b12a6fb5a'::uuid, 'D сонголтод „广为遗传“ гэдэг үг буруу — „遗传“ (удамших, биологийн ойлголт) нь номын тархалтын тухай ярихад тохирохгүй, харин „流传“ (дэлгэрэх, тархах) гэсэн үг байх ёстой. Бусад сонголтууд зөв.'),
  ('fc610339-e747-4c7e-a37e-70265814981b'::uuid, 'B сонголтод „谨慎的态度找工作“ гэдэг хэсэгт „用/以“ (ашиглан) угтвар үг дутуу — зөв нь „用谨慎的态度找工作“ байх ёстой байсан тул гишүүн дутуу алдаатай. Бусад сонголтууд бүтэц зөв.'),
  ('ac664c12-196d-4638-b367-b6762d024e67'::uuid, 'C сонголтод „因而“ (иймд) холбоос үг логикийн хувьд тохирохгүй — өдөрт 20 цаг унтдаг нь ихээхэн хүч зарцуулна гэсэн дүгнэлттэй холбогдохгүй, харин эсрэгээрээ хүч хуримтлуулна. Бусад сонголтууд зөв.'),
  ('629403f6-8e9b-462b-b5c1-87d9996563d8'::uuid, 'C сонголтод „它是把...经过叫倒叙“ гэдэг өгүүлбэрийн эхлэл, төгсгөл зохицохгүй байна — „它是“-г хасаад „把事件的结局先写出来，...叫倒叙“ гэвэл зөв өгүүлбэр болно. Бусад сонголтууд зөв.'),
  ('78aa0f6e-f993-41a8-8429-5e0a4b932078'::uuid, 'D сонголтод „它有望被取代煤、石油和天然气“ гэдэгт идэвхт/идэвхгүй хэлбэр буруу хэрэглэгдсэн — 可燃冰 (шатдаг мөс) нь нүүрс, газрын тосыг ОРЛОХ тухай өгүүлж байгаа тул „被“-гүйгээр „取代“ гэх ёстой. Бусад сонголтууд зөв.'),
  ('9007bce5-eff5-4941-860d-5e4a9d6b329f'::uuid, 'B сонголтод „高于男性之上“ гэдэг үг давхардсан — „高于“ (илүү өндөр) нь өөрөө „-аас дээгүүр“ гэсэн утгатай тул ард нь дахин „之上“ нэмэх шаардлагагүй. Бусад сонголтууд зөв.'),
  ('684c993c-8f00-4a9d-ab24-a75efb5c3440'::uuid, 'B сонголтод „情绪状态的情况“ гэдэг хэллэг давхардсан — „状态“ (байдал) ба „情况“ (нөхцөл байдал) ижил утгатай үгсийг зэрэг хэрэглэсэн тул илүүц гишүүнтэй алдаа гарчээ. Бусад сонголтууд зөв.'),
  ('18c49afd-8bcc-40bd-bc57-2155b30fc027'::uuid, 'Цоорхойн өмнө „一__优质的早餐“ гэдэгт хоолны тоолуур үг „顿“ (удаа) хэрэгтэй; „思维敏捷，__灵活“ гэдэгт „反应“ (хариу үйлдэл) нь 敏捷-тай хослон „思维敏捷，反应灵活“ тогтсон хэллэг үүсгэдэг; „提高...__“ гэдэгт „效率“ (үр ашиг) тохирно. Тиймээс A зөв.'),
  ('78f5c716-5529-43cf-8a5c-c491b6bbfeed'::uuid, '„不计一切代价地去做“ (ямар ч үнээр хэрэгжүүлэх) гэдэгтэй утгын хувьд „全力以赴“ (бүх хүчээ дайчлах) хамгийн ойр, „无数个想法“ гэдэгт „无数“ (тоо томшгүй олон) тохирно. B доторх „心甘行愿“ дур зоргоороо гэсэн утгатай тул таарахгүй, тиймээс C зөв.'),
  ('2dd926e7-0f0e-4e02-a4c8-72d21d1f6a4f'::uuid, '„不少电视剧也在这里__“ гэдэгт „拍摄“ (зураг авах) тохирно, „许多国外旅行者把它__为...必游景点“ гэдэгт „列为“ (жагсаах, тооцох) гэсэн тогтмол хэллэг хэрэглэгддэг тул B зөв. C доторх „演绎“, „追“ нь энэ бүтэцтэй нийцэхгүй.'),
  ('002aabc1-4739-49b3-9cbc-fc0f41d1eafd'::uuid, '„几十道__“ гэдэгт „工序“ (ажлын дараалал) нь „道“ тоологчтой хослон „几十道工序“ болдог, „纯手工__而成“ гэдэгт „制作“ тохирно, „构图__“ гэдэгт „别致“ (өвөрмөц сайхан) тохирно. Тиймээс C зөв.'),
  ('afef82f7-bbff-4df1-a413-2b097e302d80'::uuid, '„在一切社交__中“ гэдэгт „场合“ (тохиолдол, нөхцөл байдал) тогтмол хэллэг болдог, „使妇女陷于__、困难的处境“ гэдэгт „尴尬“ (эвгүй байдал), „则__着男士的失职“ гэдэгт „意味“ (утга илэрхийлэх) тохирно. Тиймээс B зөв.'),
  ('2fe353a4-0825-4af5-9a76-0a118ca74fa8'::uuid, '„以...而__“ гэдэгт „举世闻名“ (дэлхий даяар алдартай) нь „以...而闻名“ гэсэн тогтмол хэллэгтэй нийцнэ; „许多__灭绝的动物“ гэдэгт „濒临灭绝“ (устах ирмэгт байгаа) тогтмол хэллэг; „__大熊猫和金丝猴等“ гэдэгт „包括“ (үүнд орно) тохирно. A зөв.'),
  ('a6957315-f951-458c-96ff-94d934dc7912'::uuid, '„也不会总是__“ гэдэгт „春风得意“ (бүх зүйл сайхан явагдах), „不如意甚至__面前“ гэдэгт „挫折“ (бэрхшээл), „以平和的__“ гэдэгт „心态“ (сэтгэл зүйн байдал), „__的绽放“ гэдэгт „灿烂“ (гэрэлт) тохирно. Тиймээс D зөв.'),
  ('c3b5a6aa-d39e-4d8d-9f9b-ca0b407036a8'::uuid, '„个性__人情世故“ гэдэгт „以及“ (мөн, түүнчлэн) хоёр нэр үгийг холбоно; „很__地概括“ гэдэгт „巧妙“ (уран овсгоотой) тохирно; „具有了__“ гэдэгт „人性“ (хүн чанар) тохирно; „非但不...__觉得“ гэдэгт „反倒“ (харин ч эсрэгээрээ) тохирно. B зөв.'),
  ('ffce24da-7ddf-44fa-b5d7-e541063441b6'::uuid, '„__不要往锅里浇水“ гэдэгт „千万“ (ямар ч тохиолдолд) сануулгын өгүүлбэрт хэрэглэгддэг; „不能__空气“ гэдэгт „隔绝“ (тусгаарлах) нь „隔绝空气“ гэсэн тогтмол хэллэг; „与空气的__面积“ гэдэгт „接触“ (хүрэлцэх); „越烧越__“ гэдэгт „旺“ (улам хүчтэй шатах) тохирно. A зөв.'),
  ('34c543ba-3f91-46a4-b396-9c4cdcf94f76'::uuid, 'Энэ асуултын өгөгдөл гажигтай харагдана: `stem` нь „情绪污染“ (сэтгэл санааны халдвар) сэдэвтэй боловч `options`-д гарч буй өгүүлбэрүүд огт өөр — гараг, нарны тухай агуулгатай тул эх бичвэртэй нийцэхгүй байна. Иймд зөвхөн өгөгдсөн зөв хариулт B „它受到的太阳照射比地球强得多“ (тэр гараг нарны туяаг дэлхийгээс хавьгүй хүчтэй хүлээн авдаг) гэдгийг тэмдэглэж, эх материалтай тулгаж үзэхийг зөвлөж байна.'),
  ('a91427cf-bf29-4ea8-8a51-35ef39f799c4'::uuid, 'Хоосон зайны өмнө „产生强烈的震动“ (хүчтэй доргилт үүсгэдэг) гэж байгаа тул дараа нь энэ доргилт хүний биед тохиолдвол гэсэн таамаглал орох ёстой. B „这种震动如果发生在人的身上“ (энэ доргилт хэрэв хүний биед тохиолбол) нь ард нь ирэх „恐怕早就得脑震荡了“-тэй логикоор шууд холбогдоно.'),
  ('89a84b5b-a21e-4c53-a4ab-d85661799ccb'::uuid, 'D „就可以知道它为什么不会得脑震荡了“ (яагаад тэр тархины донтолтод өртдөггүйг мэдэж болно) нь өмнөх „只要我们观察一下啄木鸟头部的生理构造“ (толгойн бүтцийг ажигласнаар) гэсэн нөхцөлт өгүүлбэрийн үр дүн болж холбогдоно.'),
  ('5984819f-e1cf-4607-a76c-0706b70b0b3c'::uuid, 'C „形成一个避震功能极佳的保护垫“ (маш сайн доргилт шингээх хамгаалалтын дэрлэг үүсгэдэг) нь өмнөх „头骨骨质呈海绵状“ (яс нь хөвөн мэт сүвэрхэг) гэдгийн үр дагавар болж, дараагийн „可以有效地避免撞击“-тэй утгаараа нийцнэ.'),
  ('c594752f-60a6-4b15-9ac8-da5617192097'::uuid, '„舌头底部的结缔组织延伸环绕脑部“ (хэлний доод холбогч эд тархийг тойрон сунадаг) гэсний дараа A „同样可以起到保护脑部的作用“ (мөн адил тархийг хамгаалах үүрэгтэй) гэсэн дүгнэлт логикоор дараалж байна.'),
  ('5155003d-9266-404d-86a4-a5d9624a9621'::uuid, '„设计头盔和安全帽时“ (дуулга, малгай зохиохдоо) гэсний дараа E „在帽顶与头顶之间留有空隙“ (малгайн орой ба толгойн хооронд зай үлдээх) гэдэг нь дараагийн „填充这个空隙“ өгүүлбэрийн „空隙“ (зай) гэдэг үгтэй шууд холбогдоно.'),
  ('44828d7b-8ec3-4f97-8a9e-2b9da631efc4'::uuid, '„从太阳系诞生的情形来看“ (нарны аймаг үүссэн үеийн байдлаас харвал) гэсний дараа E „金星、火星与地球几乎是同时期形成“ (сугар, ангараг нь дэлхийтэй бараг ижил үед бий болсон) нь ард нь орох „也几乎由同样的物质组成“-той утгын хувьд зэрэгцэн орно.'),
  ('00187de2-f6ff-49af-96ea-8fb750d735d1'::uuid, '„根本的原因是地球上有液态水“ (үндсэн шалтгаан бол дэлхий дээр шингэн ус байдаг явдал) гэсний дараа D „其他行星上却没有“ (бусад гараг дээр харин байхгүй) нь харьцуулалт хийж, дараагийн „液态水正是产生生命必不可少的条件“-тэй холбогдоно.'),
  ('7acd97e7-16ed-47d2-9b9b-046d74719fbd'::uuid, '„金星离太阳更近“ (сугар гараг нар руу илүү ойр) гэсний дараа B „它受到的太阳照射比地球强得多“ (нарны туяаг дэлхийгээс хавьгүй хүчтэй авдаг) гэдэг нь дараагийн усны уур нарны хэт ягаан туяанд задардаг өгүүлбэртэй логикоор холбогдоно.'),
  ('15e36b82-ff2c-4dc4-a950-853c35d4f4e8'::uuid, '„金星尚且如此“ (сугар гараг ч гэсэн ийм байхад) гэсний дараа C „比金星还靠近太阳的水星就更不用说了“ (сугараас ч нар руу ойр буд гарагийг дурдах ч хэрэггүй) нь эрчимжүүлэх логик холбоос болж, алс гарагуудын тухай өгүүлбэртэй зэрэгцэнэ.'),
  ('e9fb850d-945d-41df-be19-95936608d7a3'::uuid, '„由此可见“ (үүнээс харахад) гэсний дараа A „地球所处的位置真是妙不可言“ (дэлхийн байрлал үнэхээр гайхамшигтай) гэдэг нь өмнөх бүх шалтгааныг нэгтгэсэн эцсийн дүгнэлт болж байна.'),
  ('4f23f2e6-40de-4594-bbd7-c219bbdfbe79'::uuid, 'Ардын үг „娇儿宠称多“ (хайртай хүүхдэд олон тоглуулах нэр өгдөг) гэдгийг иш татсан нь дараагийн „正说明山西人对它的重视和喜爱“ (Шаньси хүмүүс гурилан хоолыг үнэлж хайрладгийг харуулна) гэсэн өгүүлбэртэй шууд холбогддог тул C зөв. A, D зөвхөн нэг талыг л дурдсан.'),
  ('611f66d3-7a69-4108-addc-8db130e58bf4'::uuid, '„过年吃''接年面''，取岁月延绵之意，希望年年有余“ (Шинэ жилээр 接年面 идэх нь он жил үргэлжлэх, жил бүр илүүдэлтэй байхыг ерөөх утгатай) гэдэгт үндэслэн C „日子美满长久“ хамгийн ойр утгатай. A, B, D эх бичвэрт дурдагдаагүй.'),
  ('7f248b05-dadf-41b3-9ad2-25c2aea84d2f'::uuid, '„山西面食制法繁多“ (Шаньси гурилан хоолны хийх арга олон янз) гэж шууд бичсэн тул A „制作方法多“ зөв. B, D эх бичвэрт байхгүй бөгөөд „一般家庭主妇能用...做成数十种面食“ гэж эсрэгээр өгүүлсэн байна.'),
  ('eb0e7b08-672a-430c-a3ee-c2f096513ff5'::uuid, 'Текст нь Шаньси гурилан хоолны түүх, нэр, төрөл, соёлын ач холбогдлыг ерөнхийд нь өгүүлж байгаа тул A „山西面食解读“ (Шаньси гурилан хоолны тайлбар) гарчиг болоход хамгийн тохиромжтой, B, C, D зөвхөн нэг талыг л хамардаг.'),
  ('4488d404-fbcc-4988-acf8-296879b58495'::uuid, '钱钟书-ийн „窗把风和太阳逗引进来，使屋子里也关着一部分春天“ (цонх салхи, наранг оруулж, өрөөнд хавар оруулж ирдэг) ишлэлийн дараа зохиогч „给房屋以阳光、空气与视眼“ гэж тайлбарласан тул B „实用功能“ (практик үүрэг) зөв.'),
  ('dea6d2cd-128b-460d-84f8-d73c9cdcc7ca'::uuid, '„空窗本身不作景象，只在组景中起景框作用“ (нүхэн цонх өөрөө зураг биш, зөвхөн бусад зургийг хүрээлэх үүрэгтэй) гэдэгт үндэслэн B зөв. A эсрэгээрээ, C, D эх бичвэрт байхгүй.'),
  ('c2e6194f-f129-49b6-9fab-0eab067470b4'::uuid, '„窗户的造型几乎100%都着眼于实用，窗的魅力在现代建筑中日益衰退“ (орчин үеийн цонх зөвхөн практик талдаа анхаарсан, гоо сайхны татам чанар нь буурч байна) гэдэгт үндэслэн C „忽略了艺术性“ зөв.'),
  ('b1e15f87-364f-4752-ae31-6c33b00436c9'::uuid, '„甲骨文的''窗''为''洞口''的直观白描“ (эртний ястай яс дээрх бичгээр ''цонх'' гэдэг нь ''нүх'' гэсэн үгийг шууд дүрсэлсэн) гэдэгт үндэслэн A „窗最初指的是洞口“ зөв.'),
  ('f11ab280-a4f1-41e9-a8fa-b0664cdb0b74'::uuid, '3-р догол мөрөнд „我们哭泣的原因变得更多了...它所携带的信息，远不止身体不适或生理需求那么简单了“ гэж байгаа тул „这一变化“ нь D „哭泣携带的信息变复杂了“ гэсэн утгатай тохирно.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('fb54a481-8b35-4a32-852b-3af32fa349cd'::uuid, '„反射性的泪水...这两种眼泪虽然功能不同，但具有相似的化学成分“ (энгийн болон рефлексийн нулимс химийн найрлагаараа төстэй) гэдэгт үндэслэн D „与眨眼时的泪水成分相似“ зөв.'),
  ('645178af-2aaa-4819-b8f9-2300fe0b0734'::uuid, '„青春期后的女性体内具有高浓度的催乳素，这种激素使得她们比男人更爱哭“ (өсвөр насны эмэгтэйчүүдийн биед пролактин гормон их байдаг тул тэд эрчүүдээс илүү уйлдаг) гэдэгт үндэслэн A „催乳素过多“ зөв.'),
  ('5eb41620-1518-4908-be7c-c34495bdba84'::uuid, '„哭泣时流出的眼泪能清除人体内的过多激素...把这些多余的化学物质''冲走''“ (нулимс илүүдэл гормоныг арилгадаг) гэдэгт үндэслэн A „哭泣能缓解情绪“ зөв. C буруу, учир нь калийн хамгийн их агуулагдсан нь мэдрэмжийн нулимс.'),
  ('cce5a57d-8fd1-412d-8825-c0a3a8143eb0'::uuid, '桓公 „我一点儿病也没有，用不着治疗“, „我才不信这一套“ гэж хэлсэн нь扁鹊-ийн үгэнд итгэдэггүйг харуулж байгаа тул C „桓公不信扁鹊的话“ зөв.'),
  ('bb6790ab-075f-4c2a-b7ef-7fa4cb854262'::uuid, '扁鹊 гурав дахь удаагаа „您的病已经发展到肠胃了“ гэж хэлсэн тул A „病入肠胃“ зөв.'),
  ('1ba710a0-ae72-4a20-b80e-dbb2a9c0b488'::uuid, '扁鹊-ийн тайлбар „可眼下他已病入骨髓，再高明的医术也无力回天“ (одоо өвчин нь ясны чөмөгт хүрсэн тул хамгийн сайн эмч ч аргалж чадахгүй) гэдэгт үндэслэн B „桓公已无药可救“ зөв.'),
  ('05a9499c-1aae-47e6-b4a9-bfb69822879e'::uuid, '„对于一切不好的事情，都不能讳疾忌医，而应正视问题，尽早采取措施，防微杜渐“ (муу зүйлийг нуухгүй, эрт арга хэмжээ авах ёстой) гэдэгт үндэслэн C „要及时清除隐患“ зөв.'),
  ('e39ec81b-1159-40e4-acda-33643cee60d1'::uuid, '„所谓极昼，就是太阳终日都出现在地平线上的一种自然现象“ (нар өдөржин тэнгэрийн хаяанаас дээш харагдах үзэгдэл) гэдэгт үндэслэн B „太阳终日不落“ зөв.'),
  ('8b79a68b-230c-490e-8590-b764c4622440'::uuid, '„考察人员做过很多尝试，比如加厚帐篷...甚至还尝试过在冰川和积雪下穴居等“ (мөстлөгийн дор нүх ухаж амьдарч байсан) гэдэгт үндэслэн C „在冰雪下挖洞居住“ зөв.'),
  ('15cddb61-2b8e-4e40-aeb8-dc49d64ad3d9'::uuid, '„匪夷所思“ гэдэг нь ердийн ойлголтоор төсөөлөхөд бэрх гэсэн утгатай тогтмол хэллэг тул D „根据常理难以想象“ зөв.'),
  ('5759dddc-9667-4d31-9359-429beba665df'::uuid, '„所以不管对待人生中的好运、甜蜜，还是那些坎坷、磨难，都应坦然处之“ (амьдралын аз жаргал, зовлонг тайван зохицуулах ёстой) гэдэгт үндэслэн D „从容面对人生苦乐“ зөв.')
) as v(id, explanation)
 where t.id = v.id;

